#!/usr/bin/env bash
# Generated by scripts/build-deploy.sh — do not edit directly.
# setup-user-hooks.sh -- Deploys Claude Code hooks and preferences to ~/.claude/settings.json
# Self-contained: hook script and preferences are embedded below. No repo needed.
# Safe to re-run -- merges managed fields without clobbering existing settings.
#
# Managed fields: hooks.SessionEnd, hooks.PreToolUse, autoMemoryEnabled, alwaysThinkingEnabled, effortLevel
# Preserved: permissions, enabledPlugins, all other fields
#
# Hooks deployed:
#   SessionEnd: session-archive.sh (archives transcripts to user repo)
#   PreToolUse[Bash]: standing-order-guard.sh (enforces standing orders on Bash commands)

set -euo pipefail

# --- Flag parsing ---
DRY_RUN=false
FORCE=false
for arg in "$@"; do
    case "$arg" in
        --dry-run) DRY_RUN=true ;;
        --force)   FORCE=true ;;
    esac
done
[ "${AITOOLS_DRY_RUN:-}" = "1" ] && DRY_RUN=true

# --- Shared library ---
# aitools-lib.sh -- shared helpers for all aitools bash scripts
# Sourced, not executed directly. No shebang, no set -euo pipefail (caller sets it).
#
# Provides: platform detection, display_path, read_config_key, logging_init,
# log/log_ok/log_error/log_warn/log_detail, invoke_ai, write_summary,
# show_summary, SORT_KEYS_JS, normalize_json.
#
# Usage:
#   source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/aitools-lib.sh"
#   logging_init "script-name"
#
# Entry points (aitools, aitools-install) override log functions after sourcing
# for specialized logging (file-only, JSONL, etc.).

# ---------------------------------------------------------------------------
# Platform detection
# ---------------------------------------------------------------------------
IS_MACOS=false
IS_WINDOWS=false
case "$(uname -s)" in
    Darwin*)              IS_MACOS=true ;;
    MINGW*|MSYS*|CYGWIN*) IS_WINDOWS=true ;;
esac

# ---------------------------------------------------------------------------
# Log directory (platform-aware)
# ---------------------------------------------------------------------------
AITOOLS_LOG_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/aitools"
$IS_MACOS && AITOOLS_LOG_DIR="$HOME/Library/Logs/aitools"

# ---------------------------------------------------------------------------
# Module-level counters (safe for sourcing without logging_init under set -u)
# ---------------------------------------------------------------------------
ERRORS=0
WARNINGS=0

# ---------------------------------------------------------------------------
# Display-friendly path (native Windows on MSYS, no-op elsewhere)
# ---------------------------------------------------------------------------
display_path() {
    if command -v cygpath &>/dev/null; then
        cygpath -w "$1"
    else
        printf '%s' "$1"
    fi
}

# ---------------------------------------------------------------------------
# Config reader (pure bash, handles UTF-8 BOM)
# ---------------------------------------------------------------------------
# Read a top-level string value from a JSON config file.
# Handles UTF-8 BOM (PowerShell 5.x writes one) and JSON-escaped backslashes.
read_config_key() {
    local file="$1" key="$2"
    [ -f "$file" ] || return 1
    local val
    val=$(tr -d '\357\273\277' < "$file" \
        | grep -o "\"$key\"[[:space:]]*:[[:space:]]*\"[^\"]*\"" \
        | head -1 \
        | cut -d'"' -f4)
    [ -n "$val" ] || return 1
    # Unescape JSON backslashes: \\ -> \
    printf '%b' "$val"
}

# ---------------------------------------------------------------------------
# Logging init
# ---------------------------------------------------------------------------
# Sets SCRIPT_NAME, LOG_DIR, LOG_FILE; resets ERRORS, WARNINGS; creates log dir.
# Usage: logging_init "setup-foo"
logging_init() {
    SCRIPT_NAME="${1:?logging_init requires a script name}"
    LOG_DIR="$AITOOLS_LOG_DIR"
    LOG_FILE="$LOG_DIR/deploy.log"
    mkdir -p "$LOG_DIR"
    ERRORS=0
    WARNINGS=0
}

# ---------------------------------------------------------------------------
# Standard logging (Pattern A: console + log file, with [level] tag)
# ---------------------------------------------------------------------------
log() {
    local level="${2:-info}"
    local ts; ts="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
    local line="[$ts] [$SCRIPT_NAME] [$level] $1"
    printf '%s\n' "$line" >> "$LOG_FILE"
    case "$level" in
        error) printf '\033[31m%s\033[0m\n' "$line" ;;
        warn)  printf '\033[33m%s\033[0m\n' "$line" ;;
        *)     printf '%s\n' "$line" ;;
    esac
}
log_ok()    { log "$1" "ok"; }
log_error() { log "$1" "error"; ERRORS=$((ERRORS + 1)); }
log_warn()  { log "$1" "warn"; WARNINGS=$((WARNINGS + 1)); }
log_detail() {
    local ts; ts="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
    printf '[%s] [%s] [detail] %s\n' "$ts" "$SCRIPT_NAME" "$1" >> "$LOG_FILE"
}

# ---------------------------------------------------------------------------
# Agentic AI invocation -- generalized wrapper for claude/agent CLI
# ---------------------------------------------------------------------------
# Purpose: Standardized AI CLI invocation with speed/permission tiers,
#   validation callbacks, automatic retry, and telemetry logging.
# Inputs: SPEED (fast/balanced/quality), PERMISSIONS (none/readonly/full/
#   dangerous), VALIDATE_FN (function name, receives output as $1),
#   MAX_RETRIES (retry count on validation failure). Prompt from stdin.
# Expected output: Raw AI-generated text on stdout.
# Validation: Caller-provided VALIDATE_FN must return 0 (pass) or 1 (fail)
#   and set AI_REJECT_REASON on failure.
# Known limitations: Agent CLI has no --model flag; speed is hint-only via
#   prompt prefix. Retry prepends rejection reason but may not fix structural
#   issues (e.g., model always wrapping in code fences).

# File-only AI telemetry logging (avoids stdout capture interference when
# invoke_ai output is captured via $()). Does not increment ERRORS/WARNINGS --
# callers decide whether to count invoke_ai failures.
_ai_log() {
    local ts; ts="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
    printf '[%s] [%s] [%s] %s\n' "$ts" "$SCRIPT_NAME" "${2:-info}" "$1" >> "${LOG_FILE:-/dev/null}"
}

AI_REJECT_REASON=""

invoke_ai() {
    local speed="${1:-balanced}"
    local permissions="${2:-none}"
    local validate_fn="${3:-}"
    local max_retries="${4:-0}"

    AI_REJECT_REASON=""

    # Read prompt from stdin
    local prompt
    prompt=$(cat)

    # Detect backend
    # command -v exempt: existence check with explicit fallback chain
    local cli_cmd=""
    if command -v claude >/dev/null 2>&1; then
        cli_cmd="claude"
    elif $IS_WINDOWS; then
        # Windows Git Bash: agent may be on PowerShell PATH only
        local agent_path
        agent_path=$(pwsh -NoProfile -Command \
            'Get-Command agent -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Source' \
            2>/dev/null) || true  # pwsh may not be installed; fallback is no agent CLI
        if [ -n "$agent_path" ]; then cli_cmd="agent"; fi
    elif command -v agent >/dev/null 2>&1; then
        cli_cmd="agent"
    fi

    if [ -z "$cli_cmd" ]; then
        AI_REJECT_REASON="No AI CLI available (claude or agent)"
        _ai_log "AI invocation: no CLI available (claude or agent)" "error"
        return 1
    fi

    # Build CLI flags
    local -a flags=()

    if [ "$cli_cmd" = "claude" ]; then
        flags+=("-p" "--no-session-persistence")
        # Speed mapping (claude CLI: explicit model + effort)
        case "$speed" in
            fast)     flags+=("--model" "haiku" "--effort" "low") ;;
            balanced) flags+=("--model" "sonnet") ;;
            quality)  flags+=("--model" "opus" "--effort" "high") ;;
        esac
        # Permission mapping
        case "$permissions" in
            none)      flags+=("--allowedTools" "") ;;
            readonly)  flags+=("--allowedTools" "Read Glob Grep") ;;
            full)      ;; # default -- no restriction
            dangerous) flags+=("--dangerously-skip-permissions") ;;
        esac
        # System prompt hints for speed tiers
        case "$speed" in
            fast)    flags+=("--append-system-prompt" "Be concise and direct.") ;;
            quality) flags+=("--append-system-prompt" "Take your time. Be thorough.") ;;
        esac
    else
        # Agent CLI -- no --model flag; speed via prompt prefix only
        flags+=("-p" "--trust")
        # Permission mapping
        case "$permissions" in
            none)      flags+=("--mode" "ask") ;;
            readonly)  flags+=("--mode" "plan") ;;
            full)      ;; # default
            dangerous) flags+=("--force") ;;
        esac
    fi

    # Speed prefix for agent CLI (no model flag available)
    local speed_prefix=""
    if [ "$cli_cmd" = "agent" ]; then
        case "$speed" in
            fast)    speed_prefix="Be concise and direct. Prioritize speed.\n\n" ;;
            quality) speed_prefix="Take your time. Be thorough and precise.\n\n" ;;
        esac
    fi

    # Retry loop
    local attempt=0
    local current_prompt="$prompt"

    while [ "$attempt" -le "$max_retries" ]; do
        attempt=$((attempt + 1))

        _ai_log "AI invocation: speed=$speed backend=$cli_cmd attempt=$attempt"

        local full_prompt
        full_prompt=$(printf '%b%s' "$speed_prefix" "$current_prompt")

        local output
        # Suppress set -e abort; CLI may exit non-zero on model errors
        output=$(printf '%s' "$full_prompt" | "$cli_cmd" "${flags[@]}" 2>&1) || true

        if [ -z "$output" ]; then
            AI_REJECT_REASON="Empty output from $cli_cmd"
            _ai_log "AI invocation: speed=$speed backend=$cli_cmd attempt=$attempt result=empty" "warn"
            if [ "$attempt" -le "$max_retries" ]; then
                current_prompt=$(printf 'Your previous output was empty. Try again.\n\n%s' "$prompt")
                continue
            fi
            return 1
        fi

        # Validate if function provided
        if [ -n "$validate_fn" ]; then
            if ! "$validate_fn" "$output"; then
                [ -z "$AI_REJECT_REASON" ] && AI_REJECT_REASON="Validation failed"
                _ai_log "AI invocation: speed=$speed backend=$cli_cmd attempt=$attempt result=rejected reason=$AI_REJECT_REASON" "warn"
                while IFS= read -r _rej_line; do
                    log_detail "ai-rejected: $_rej_line"
                done <<< "$output"
                if [ "$attempt" -le "$max_retries" ]; then
                    current_prompt=$(printf 'Your previous output was rejected: %s. Try again.\n\n%s' \
                        "$AI_REJECT_REASON" "$prompt")
                    continue
                fi
                _ai_log "AI invocation: speed=$speed backend=$cli_cmd exhausted after $attempt attempts" "warn"
                return 1
            fi
        fi

        # Success
        _ai_log "AI invocation: speed=$speed backend=$cli_cmd attempt=$attempt result=accepted"
        printf '%s' "$output"
        return 0
    done

    return 1
}

# ---------------------------------------------------------------------------
# Summary writer (3-arg: category, tool, detail)
# ---------------------------------------------------------------------------
write_summary() {
    if [ -n "${AITOOLS_SUMMARY_FILE:-}" ]; then
        local cat="$1"
        # Auto-promote OK to WARN when warnings have been logged
        if [ "$cat" = "OK" ] && [ "${WARNINGS:-0}" -gt 0 ]; then
            cat="WARN"
        fi
        printf '%s|%s|%s\n' "$cat" "$2" "$3" >> "$AITOOLS_SUMMARY_FILE"
    fi
}

# ---------------------------------------------------------------------------
# Backup a file before overwriting. Keeps at most $max_backups copies.
# ---------------------------------------------------------------------------
backup_file() {
    local file="$1" max_backups=20
    [ -f "$file" ] || return 0
    local ts
    ts=$(date -u +%Y-%m-%dT%H%M%SZ)
    cp "$file" "${file}.bak.${ts}"
    # Prune oldest beyond limit
    ls -1t "${file}.bak."* 2>/dev/null | tail -n +$((max_backups + 1)) | xargs rm -f 2>/dev/null
    log "Backed up $(display_path "$file")"
}

# ---------------------------------------------------------------------------
# Backup a directory before modifying managed files. Keeps at most $max_backups copies.
# ---------------------------------------------------------------------------
backup_dir() {
    local dir="$1" max_backups=5
    [ -d "$dir" ] || return 0
    local file_count
    file_count=$(find "$dir" -maxdepth 1 -name '*.md' -type f | wc -l | tr -d ' ')
    if [ "$file_count" -eq 0 ]; then
        return 0
    fi
    local ts
    ts=$(date -u +%Y-%m-%dT%H%M%SZ)
    if ! cp -R "$dir" "${dir}.bak.${ts}"; then
        log_warn "Could not back up $(display_path "$dir") -- proceeding without backup"
        return 0
    fi
    local old_backups
    old_backups=$(find "$(dirname "$dir")" -maxdepth 1 -name "$(basename "$dir").bak.*" -type d \
        | sort -r | tail -n +$((max_backups + 1)))
    if [ -n "$old_backups" ]; then
        printf '%s\n' "$old_backups" | while IFS= read -r old_dir; do
            rm -rf "$old_dir"
            log "Pruned old backup: $(display_path "$old_dir")"
        done
    fi
    log "Backed up $(display_path "$dir") ($file_count managed files)"
}

# ---------------------------------------------------------------------------
# Deploy state tracking: manifest + shadow copies for auto-deploy detection.
# Tracks what was last deployed to each managed file.
# ---------------------------------------------------------------------------
_DEPLOY_STATE_DIR="$HOME/.aitools/deploy-state"
_DEPLOY_MANIFEST=""

get_content_hash() {
    printf '%s' "$1" | sha256sum | cut -d' ' -f1
}

_deploy_state_key() {
    local file_path="$1"
    # Normalize: strip $HOME prefix, use forward slashes
    printf '%s' "$file_path" | perl -pe "s{^\Q$HOME\E/}{}"
}

initialize_deploy_state() {
    local manifest_path="$_DEPLOY_STATE_DIR/manifest.json"
    if [ -f "$manifest_path" ]; then
        _DEPLOY_MANIFEST=$(cat "$manifest_path")
    else
        _DEPLOY_MANIFEST='{"version":1,"files":{}}'
    fi
}

get_deploy_state_hash() {
    local file_path="$1"
    if [ -z "$_DEPLOY_MANIFEST" ]; then initialize_deploy_state; fi
    local key
    key=$(_deploy_state_key "$file_path")
    # node is already a dependency (used by read_config_key)
    printf '%s' "$_DEPLOY_MANIFEST" | node -e "
        const m = JSON.parse(require('fs').readFileSync('/dev/stdin','utf8'));
        const f = m.files || {};
        const e = f[process.argv[1]];
        if (e && e.hash) process.stdout.write(e.hash);
    " "$key" 2>/dev/null
}

update_deploy_state() {
    local file_path="$1"
    local content="$2"
    if [ -z "$_DEPLOY_MANIFEST" ]; then initialize_deploy_state; fi
    local key hash ts
    key=$(_deploy_state_key "$file_path")
    hash=$(get_content_hash "$content")
    ts=$(date -u +%Y-%m-%dT%H:%M:%SZ)

    mkdir -p "$_DEPLOY_STATE_DIR"

    # Update manifest via node
    _DEPLOY_MANIFEST=$(printf '%s' "$_DEPLOY_MANIFEST" | node -e "
        const m = JSON.parse(require('fs').readFileSync('/dev/stdin','utf8'));
        if (!m.files) m.files = {};
        m.files[process.argv[1]] = { hash: process.argv[2], deployedAt: process.argv[3] };
        process.stdout.write(JSON.stringify(m, null, 2));
    " "$key" "$hash" "$ts" 2>/dev/null)

    printf '%s\n' "$_DEPLOY_MANIFEST" > "$_DEPLOY_STATE_DIR/manifest.json"

    # Write shadow copy
    local shadow_path="$_DEPLOY_STATE_DIR/shadows/$key"
    mkdir -p "$(dirname "$shadow_path")"
    printf '%s' "$content" > "$shadow_path"
}

get_deploy_shadow() {
    local file_path="$1"
    local key
    key=$(_deploy_state_key "$file_path")
    local shadow_path="$_DEPLOY_STATE_DIR/shadows/$key"
    if [ -f "$shadow_path" ]; then
        cat "$shadow_path"
    fi
}

# ---------------------------------------------------------------------------
# Non-agentic 3-way merge using shadow as common ancestor.
# Backend: git merge-file (guaranteed prerequisite -- no discovery needed).
# Sets AUTO_MERGED_CONTENT on clean merge. Returns 0 on success, 1 on failure.
# ---------------------------------------------------------------------------
AUTO_MERGED_CONTENT=""
try_auto_merge() {
    local local_content="$1"
    local ancestor_content="$2"
    local source_content="$3"
    AUTO_MERGED_CONTENT=""

    local tmp_local tmp_ancestor tmp_source
    tmp_local=$(mktemp)
    tmp_ancestor=$(mktemp)
    tmp_source=$(mktemp)
    printf '%s' "$local_content" > "$tmp_local"
    printf '%s' "$ancestor_content" > "$tmp_ancestor"
    printf '%s' "$source_content" > "$tmp_source"

    local merged
    # 2>/dev/null: git merge-file writes conflict markers to stderr on exit 1;
    # we only want stdout. Exit code checked via $rc immediately below.
    merged=$(git merge-file -p "$tmp_local" "$tmp_ancestor" "$tmp_source" 2>/dev/null)
    local rc=$?
    rm -f "$tmp_local" "$tmp_ancestor" "$tmp_source"

    if [ "$rc" -eq 0 ]; then
        AUTO_MERGED_CONTENT="$merged"
        return 0
    fi
    return 1
}

# ---------------------------------------------------------------------------
# Merge file description lookup
# ---------------------------------------------------------------------------
# Purpose: Returns a human-readable description of a managed file for AI merge
#   prompts, providing context about the file's role in the config system.
# Inputs: $1 = file path
# Expected output: Single-line description string on stdout.
_get_merge_file_description() {
    case "$(basename "$1")" in
        CLAUDE.md) printf 'User-scope CLAUDE.md -- personal preferences and instructions for Claude Code' ;;
        *.md)      printf 'Configuration rule: %s' "$(basename "$1")" ;;
        *.json)    printf 'JSON config: %s' "$(basename "$1")" ;;
        *)         printf 'Managed file: %s' "$(basename "$1")" ;;
    esac
}

# ---------------------------------------------------------------------------
# AI merge prompt builder (initial merge)
# ---------------------------------------------------------------------------
# Purpose: Builds a structured merge prompt following the Role/Context/Task/
#   Constraints/Format pattern for merging managed configuration files.
# Inputs: $1=file_path, $2=source_content, $3=local_content, $4=diff_output
# Expected output: Complete prompt string on stdout, suitable for invoke_ai.
# Validation: validate_ai_merge_output (5 checks: conversational, fences,
#   refusal, truncation, header preservation)
# Known limitations: Very large files may hit model context limits. Files with
#   no markdown headers rely on Check 4 (length) for rewrite detection.
_ai_prompt_merge() {
    local file_path="$1"
    local source_content="$2"
    local local_content="$3"
    local diff_output="$4"

    local file_desc
    file_desc=$(_get_merge_file_description "$file_path")

    printf '%s' "You are merging a managed configuration file during automated deployment.

## What you are merging
${file_desc}

## Where changes come from
SOURCE: The canonical template, synced across machines -- the updated version being deployed
LOCAL: The user's current file on this machine, with their customizations

## What is happening
Updated configuration is being deployed. Source has changed and needs to be
incorporated without losing local customizations.

## Differences (unified diff: local vs source)
${diff_output}

## Full local file (start from this)
<LOCAL>
${local_content}
</LOCAL>

## Rules
1. Start with LOCAL as your base -- preserve all user customizations
2. Apply ONLY the changes shown in the diff
3. If a change conflicts with a local customization (contradicts its intent), keep local
4. If a change adds new content not in LOCAL, add it in the appropriate location
5. If a change updates content the user hasn't customized, apply it
6. CRITICAL: Do NOT wrap your output in markdown code fences (\`\`\`). Output raw file content ONLY
7. No commentary, no explanation, no preamble -- just the merged file content"
}

# ---------------------------------------------------------------------------
# AI merge prompt builder (refinement)
# ---------------------------------------------------------------------------
# Purpose: Builds a refinement prompt for iterating on a previous merge result
#   based on user feedback.
# Inputs: $1=source_content, $2=local_content, $3=current_merge, $4=feedback
# Expected output: Complete prompt string on stdout, suitable for invoke_ai.
# Validation: Same as initial merge (validate_ai_merge_output).
_ai_prompt_merge_refine() {
    local source_content="$1"
    local local_content="$2"
    local current_merge="$3"
    local feedback="$4"

    printf '%s' "You are refining a merged configuration file based on user feedback.

## Context
A previous merge produced CURRENT_MERGE from SOURCE + LOCAL. The user wants changes.

## SOURCE (original template)
<SOURCE>
${source_content}
</SOURCE>

## LOCAL (original user file)
<LOCAL>
${local_content}
</LOCAL>

## CURRENT MERGE (previous result)
<CURRENT_MERGE>
${current_merge}
</CURRENT_MERGE>

## User Feedback
${feedback}

## Rules
- Apply the user's feedback to CURRENT_MERGE
- Keep all content from CURRENT_MERGE not affected by the feedback
- Output the revised merged file content ONLY -- no preamble, no explanation, no markdown fences"
}

# Merge validation wrapper for invoke_ai -- captures source/local context
# via module-level variables set by _invoke_ai_merge before calling invoke_ai.
_MERGE_VALIDATE_SOURCE=""
_MERGE_VALIDATE_LOCAL=""
_merge_validate() {
    validate_ai_merge_output "$1" "$_MERGE_VALIDATE_SOURCE" "$_MERGE_VALIDATE_LOCAL"
    AI_REJECT_REASON="$MERGE_REJECT_REASON"
}

MERGE_REJECT_REASON=""

# ---------------------------------------------------------------------------
# Validate AI merge output before accepting it.
# Returns 0 if valid, 1 if invalid. Sets MERGE_REJECT_REASON on failure.
# ---------------------------------------------------------------------------
validate_ai_merge_output() {
    local output="$1"
    local source_content="$2"
    local local_content="$3"
    MERGE_REJECT_REASON=""

    # Check 1: conversational patterns (first non-empty line)
    local first_line
    first_line=$(printf '%s' "$output" | perl -ne 'if (/\S/) { print; exit }')
    if printf '%s' "$first_line" | perl -ne 'exit 0 if /^(I |Here|Sure|Certainly|Let me)/i; exit 1'; then
        MERGE_REJECT_REASON="AI responded conversationally instead of producing merged content"
        return 1
    fi

    # Check 2: markdown code fences
    if printf '%s\n' "$output" | perl -ne 'exit 0 if /^```/; END { exit 1 }'; then
        MERGE_REJECT_REASON="AI wrapped output in code fences -- need raw content"
        return 1
    fi

    # Check 3: conversational refusal patterns (not bare keywords -- content may
    # legitimately contain "permission", "access", etc.)
    if printf '%s' "$output" | perl -ne 'exit 0 if /(?:I don.t have permission|I cannot access|I.m not authorized|I need (?:your )?approval|permission denied|access denied|I.m unable to|I can.t (?:read|write|access|open|modify))/i; END { exit 1 }'; then
        MERGE_REJECT_REASON="AI indicated it couldn't perform the merge"
        return 1
    fi

    # Check 4: minimum length (output >= 50% of shorter input when shorter > 40 chars)
    local out_len src_len local_len min_input_len threshold
    out_len=$(printf '%s' "$output" | wc -c | tr -d ' ')
    src_len=$(printf '%s' "$source_content" | wc -c | tr -d ' ')
    local_len=$(printf '%s' "$local_content" | wc -c | tr -d ' ')
    if [ "$src_len" -le "$local_len" ]; then min_input_len=$src_len; else min_input_len=$local_len; fi
    threshold=$((min_input_len / 2))
    if [ "$min_input_len" -gt 40 ] && [ "$out_len" -lt "$threshold" ]; then
        MERGE_REJECT_REASON="Output too short ($out_len chars, expected ${threshold}+) -- likely truncated"
        return 1
    fi

    # Check 5: header preservation — deduplicated headers from source+local must
    # be >=60% preserved in output. Files with 0 headers pass (Check 4 handles truncation).
    local combined_headers
    combined_headers=$(printf '%s\n%s' "$source_content" "$local_content" \
        | grep -E '^#{1,6} ' | sort -u)
    local total preserved=0
    total=$(printf '%s\n' "$combined_headers" | grep -c '^' || true)  # count lines; may be 0
    if [ "$total" -gt 0 ]; then
        while IFS= read -r header; do
            [ -z "$header" ] && continue
            printf '%s' "$output" | grep -qF "$header" && preserved=$((preserved + 1))
        done <<< "$combined_headers"
        local threshold=$(( (total * 60 + 99) / 100 ))
        [ "$threshold" -lt 1 ] && threshold=1
        if [ "$preserved" -lt "$threshold" ]; then
            MERGE_REJECT_REASON="Rewrote too much ($preserved/$total section headers preserved, need 60%+)"
            return 1
        fi
    fi

    return 0
}

MERGED_CONTENT=""

# ---------------------------------------------------------------------------
# Spinner for AI operations (visual progress indicator)
# ---------------------------------------------------------------------------
_AI_SPINNER_PID=""

_start_spinner() {
    local msg="${1:-working...}"
    (
        local chars='/-\|'
        local i=0
        while true; do
            printf '\r  %s %s' "${chars:$((i % 4)):1}" "$msg" > /dev/tty
            i=$((i + 1))
            sleep 0.2
        done
    ) &
    _AI_SPINNER_PID=$!
}

_stop_spinner() {
    if [ -n "$_AI_SPINNER_PID" ] && kill -0 "$_AI_SPINNER_PID" 2>/dev/null; then
        kill "$_AI_SPINNER_PID" 2>/dev/null
        wait "$_AI_SPINNER_PID" 2>/dev/null || true  # reap; exit code irrelevant for spinner
    fi
    _AI_SPINNER_PID=""
    printf '\r  \033[K' > /dev/tty  # clear spinner line
}

# ---------------------------------------------------------------------------
# Agentic merge via invoke_ai with refinement loop.
# Uses structured prompts from _ai_prompt_merge / _ai_prompt_merge_refine.
# Sets DIFF_REVIEW_RESULT="merge" + MERGED_CONTENT, or falls back.
# ---------------------------------------------------------------------------
_invoke_ai_merge() {
    local file_path="$1"
    local source_content="$2"
    local local_content="${3:-}"
    local diff_output="${4:-}"

    # Read local from disk if not provided (backward compat)
    if [ -z "$local_content" ] && [ -f "$file_path" ]; then
        local_content=$(cat "$file_path")
    fi

    # Detect backend for transparency display
    local ai_backend="unknown"
    if command -v claude >/dev/null 2>&1; then
        ai_backend="claude"
    elif command -v agent >/dev/null 2>&1; then
        ai_backend="agent"
    fi
    local display_name
    display_name=$(basename "$file_path")
    printf '  >> AI merge: %s (balanced) -- merging %s...\n' "$ai_backend" "$display_name" > /dev/tty

    # Set validation context for _merge_validate wrapper
    _MERGE_VALIDATE_SOURCE="$source_content"
    _MERGE_VALIDATE_LOCAL="$local_content"

    local current_merge=""
    local iteration=0

    while true; do
        iteration=$((iteration + 1))
        local prompt_text

        if [ -z "$current_merge" ]; then
            prompt_text=$(_ai_prompt_merge "$file_path" "$source_content" "$local_content" "$diff_output")
        else
            local feedback
            printf '  refinement feedback: ' > /dev/tty
            IFS= read -r feedback < /dev/tty
            prompt_text=$(_ai_prompt_merge_refine "$source_content" "$local_content" "$current_merge" "$feedback")
        fi

        local merged
        _start_spinner "merging $display_name (attempt $iteration)..."
        # invoke_ai returns 1 on failure with no stdout; || true suppresses set -e abort
        merged=$(printf '%s' "$prompt_text" | invoke_ai balanced none _merge_validate 1) || true
        _stop_spinner

        # Defense-in-depth: strip leading/trailing code fences if AI ignored instructions
        if [ -n "$merged" ]; then
            merged=$(printf '%s' "$merged" | perl -0777 -pe 's/\A```[^\n]*\n//; s/\n```\s*\z//')
        fi

        if [ -z "$merged" ]; then
            printf '  >> AI merge failed (iteration %d): %s\n' "$iteration" "${AI_REJECT_REASON:-unknown error}" > /dev/tty
            log_error "AI merge failed (iteration $iteration): ${AI_REJECT_REASON:-unknown error}"
            printf '  fallback [o]verwrite / [s]kip: ' > /dev/tty
            local fb
            read -r fb < /dev/tty
            case "$(printf '%s' "$fb" | tr '[:upper:]' '[:lower:]')" in
                s) DIFF_REVIEW_RESULT="skip" ;;
                *) DIFF_REVIEW_RESULT="overwrite" ;;
            esac
            return 0
        fi

        # Show merge preview
        printf '\n  --- merged result preview (first 30 lines) ---\n' > /dev/tty
        printf '%s\n' "$merged" | head -30 | while IFS= read -r line; do
            printf '  | %s\n' "$line" > /dev/tty
        done
        local total_lines
        total_lines=$(printf '%s\n' "$merged" | wc -l | tr -d ' ')
        if [ "$total_lines" -gt 30 ]; then
            printf '  | ... (%d more lines)\n' "$((total_lines - 30))" > /dev/tty
        fi
        printf '\n  [y]es accept / [r]efine / [n]o reject: ' > /dev/tty
        local accept
        read -r accept < /dev/tty
        case "$(printf '%s' "$accept" | tr '[:upper:]' '[:lower:]')" in
            y)
                MERGED_CONTENT="$merged"
                DIFF_REVIEW_RESULT="merge"
                printf '  >> merged: AI-merged content accepted (iteration %d)\n' "$iteration" > /dev/tty
                return 0
                ;;
            r)
                current_merge="$merged"
                printf '  >> refining merge (iteration %d)...\n' "$iteration" > /dev/tty
                continue
                ;;
            *)
                printf '  >> merge rejected, falling back to overwrite\n' > /dev/tty
                DIFF_REVIEW_RESULT="overwrite"
                return 0
                ;;
        esac
    done
}

# ---------------------------------------------------------------------------
# Prompt user before overwriting a managed file with different content.
# Shows diff, attempts diff3 auto-merge, offers interactive options.
#
# Args:
#   $1 = file path (deployed file on disk)
#   $2 = new content that would be written (from source template)
#   $3 = adopt target label (e.g., "profile", "shared/") or "" to hide adopt
#   $4 = current content of local file (optional, read from disk if empty)
#   $5 = ancestor content from shadow (optional, enables diff3 merge)
#
# Sets global DIFF_REVIEW_RESULT to: "overwrite", "adopt", "merge", or "skip"
# When "merge": also sets MERGED_CONTENT with the merged result.
# Exits with code 2 on abort.
# Non-interactive / --force: sets "overwrite" and returns.
# ---------------------------------------------------------------------------
DIFF_REVIEW_RESULT=""
prompt_diff_review() {
    local file_path="$1"
    local new_content="$2"
    local adopt_label="${3:-}"
    local cur_content="${4:-}"
    local ancestor_content="${5:-}"

    DIFF_REVIEW_RESULT="overwrite"
    MERGED_CONTENT=""

    # --force or AITOOLS_FORCE: auto-overwrite
    if [ "${AITOOLS_FORCE:-}" = "1" ] || [ "${FORCE:-}" = "true" ]; then
        log_warn "Diff in $(display_path "$file_path") -- overwriting (--force)"
        return 0
    fi

    # Non-interactive: auto-overwrite
    if ! (printf '' > /dev/tty) 2>/dev/null; then
        log_warn "Diff in $(display_path "$file_path") -- overwriting (non-interactive)"
        return 0
    fi

    # Read current file if not provided
    if [ -z "$cur_content" ] && [ -f "$file_path" ]; then
        cur_content=$(cat "$file_path")
    fi

    # Context header
    printf '\n\033[33m[REVIEW]\033[0m %s differs from source.\n' \
        "$(display_path "$file_path")" > /dev/tty
    printf '  source = template (would deploy)\n' > /dev/tty
    printf '  local  = current file on disk\n\n' > /dev/tty

    # Show diff
    local diff_output
    # diff exits 1 on differences (expected), suppress set -e abort
    diff_output=$(diff -u <(printf '%s' "$new_content") <(printf '%s' "$cur_content") \
        --label "source (would deploy)" --label "local (on disk)" 2>&1) || true
    local diff_lines
    diff_lines=$(printf '%s\n' "$diff_output" | wc -l | tr -d ' ')
    if [ "$diff_lines" -le 40 ]; then
        printf '%s\n' "$diff_output" > /dev/tty
    else
        printf '%s\n' "$diff_output" | head -30 > /dev/tty
        printf '  ... (%d more lines -- full diff in deploy log)\n' \
            "$((diff_lines - 30))" > /dev/tty
        printf '%s\n' "$diff_output" >> "${LOG_FILE:-/dev/null}"
    fi

    # Attempt automatic merge if ancestor available
    if [ -n "$ancestor_content" ]; then
        printf '\n  Attempting automatic merge...\n' > /dev/tty
        if try_auto_merge "$cur_content" "$ancestor_content" "$new_content"; then
            printf '  Clean merge -- no conflicts.\n\n' > /dev/tty
            local total_m_lines preview_count
            total_m_lines=$(printf '%s\n' "$AUTO_MERGED_CONTENT" | wc -l | tr -d ' ')
            preview_count=$total_m_lines
            if [ "$preview_count" -gt 30 ]; then preview_count=30; fi
            printf '  --- merged result preview (first %d lines) ---\n' "$preview_count" > /dev/tty
            printf '%s\n' "$AUTO_MERGED_CONTENT" | head -"$preview_count" | while IFS= read -r line; do
                printf '  | %s\n' "$line" > /dev/tty
            done
            if [ "$total_m_lines" -gt 30 ]; then
                printf '  | ... (%d more lines)\n' "$((total_m_lines - 30))" > /dev/tty
            fi
            printf '\n' > /dev/tty
            if [ -n "$adopt_label" ]; then
                printf '  [a]ccept    : deploy merge + update %s\n' "$adopt_label" > /dev/tty
            else
                printf '  [a]ccept\n' > /dev/tty
            fi
            printf '  [o]verwrite\n' > /dev/tty
            printf '  [s]kip\n' > /dev/tty
            printf '  [x]abort\n' > /dev/tty
            printf '  choice [a/o/s/x]: ' > /dev/tty
            local merge_choice
            read -r merge_choice < /dev/tty
            case "$(printf '%s' "$merge_choice" | tr '[:upper:]' '[:lower:]')" in
                a)  MERGED_CONTENT="$AUTO_MERGED_CONTENT"
                    if [ -n "$adopt_label" ]; then
                        printf '  >> accepted: merge deployed + %s updated\n' "$adopt_label" > /dev/tty
                        DIFF_REVIEW_RESULT="merge-adopt"
                    else
                        printf '  >> accepted: merge deployed\n' > /dev/tty
                        DIFF_REVIEW_RESULT="merge"
                    fi
                    return 0 ;;
                s)  printf '  >> skipped: local file unchanged\n' > /dev/tty
                    DIFF_REVIEW_RESULT="skip"
                    return 0 ;;
                x)  log_error "Aborted by user"
                    exit 2 ;;
                *)  printf '  >> overwritten: source deployed to local (backup kept)\n' > /dev/tty
                    DIFF_REVIEW_RESULT="overwrite"
                    return 0 ;;
            esac
        else
            printf '  Merge has conflicts -- manual choice required.\n' > /dev/tty
        fi
    fi

    # Options (no auto-merge or merge had conflicts)
    printf '\n' > /dev/tty
    if [ -n "$adopt_label" ]; then
        printf '  [o]verwrite : source wins -> deploy to local (backup kept)\n' > /dev/tty
        printf '  [a]dopt     : local wins -> copy back to %s\n' "$adopt_label" > /dev/tty
        printf '  [m]erge     : AI-assisted merge of source + local\n' > /dev/tty
        printf '  [s]kip      : keep local as-is (no changes)\n' > /dev/tty
        printf '  [x]abort    : stop deployment\n' > /dev/tty
        printf '  choice [o/a/m/s/x]: ' > /dev/tty
    else
        printf '  [o]verwrite : source wins -> deploy to local (backup kept)\n' > /dev/tty
        printf '  [m]erge     : AI-assisted merge of source + local\n' > /dev/tty
        printf '  [s]kip      : keep local as-is (no changes)\n' > /dev/tty
        printf '  [x]abort    : stop deployment\n' > /dev/tty
        printf '  choice [o/m/s/x]: ' > /dev/tty
    fi

    local choice
    read -r choice < /dev/tty
    case "$(printf '%s' "$choice" | tr '[:upper:]' '[:lower:]')" in
        a)  if [ -n "$adopt_label" ]; then
                printf '  >> adopted: local version copied back to %s\n' "$adopt_label" > /dev/tty
                DIFF_REVIEW_RESULT="adopt"
            else
                printf '  >> overwritten: source deployed to local (backup kept)\n' > /dev/tty
                DIFF_REVIEW_RESULT="overwrite"
            fi ;;
        m)  _invoke_ai_merge "$file_path" "$new_content" "$cur_content" "$diff_output" ;;
        s)  printf '  >> skipped: local file unchanged\n' > /dev/tty
            DIFF_REVIEW_RESULT="skip" ;;
        x)  log_error "Aborted by user"
            exit 2 ;;
        *)  printf '  >> overwritten: source deployed to local (backup kept)\n' > /dev/tty
            DIFF_REVIEW_RESULT="overwrite" ;;
    esac
    return 0
}

# ---------------------------------------------------------------------------
# Deploy a managed file with diff review and deploy state tracking.
# Uses manifest to auto-deploy when user hasn't edited the local file.
# Falls back to interactive review with merge options when both sides differ.
#
# Args:
#   $1 = source content (string to deploy)
#   $2 = dest file path (deployed location)
#   $3 = tool name (for summary, e.g., "claude rules")
#   $4 = item name (for DETAIL summary, e.g., "concurrent-agents.md")
#   $5 = adopt label ("profile", "shared/", or "" to hide adopt option)
#
# Sets MANAGED_FILE_RESULT to: "created", "updated", "verified", "accept & adopt", "skipped"
# Exits with code 2 on abort (from prompt_diff_review).
# On "accept & adopt"/"skipped": does NOT write the file (caller decides).
# On "created"/"updated": writes src_content to dest + updates deploy state.
# ---------------------------------------------------------------------------
MANAGED_FILE_RESULT=""
deploy_managed_file() {
    local src_content="$1"
    local dest="$2"
    local tool_name="$3"
    local item_name="$4"
    local adopt_label="${5:-}"

    # Normalize trailing whitespace for consistent comparison.
    # Prevents round-trip diff noise (deploy -> adopt strips trailing blanks -> deploy sees diff).
    src_content=$(printf '%s' "$src_content" | perl -0777 -pe 's/[\r\n]+$/\n/')

    MANAGED_FILE_RESULT="verified"

    # Dry run: report what would happen without writing
    if [ "${DRY_RUN:-}" = "true" ]; then
        if [ -f "$dest" ]; then
            local _dr_existing
            _dr_existing=$(cat "$dest")
            _dr_existing=$(printf '%s' "$_dr_existing" | perl -0777 -pe 's/[\r\n]+$/\n/')
            if [ "$_dr_existing" = "$src_content" ]; then
                log "[DRY RUN] Unchanged: $item_name"
            else
                log "[DRY RUN] Would update: $item_name -> $(display_path "$dest")"
            fi
        else
            log "[DRY RUN] Would create: $item_name -> $(display_path "$dest")"
        fi
        return 0
    fi

    mkdir -p "$(dirname "$dest")"

    if [ -f "$dest" ]; then
        local existing
        existing=$(cat "$dest")
        existing=$(printf '%s' "$existing" | perl -0777 -pe 's/[\r\n]+$/\n/')
        if [ "$existing" = "$src_content" ]; then
            # Content identical — update deploy state (bootstraps manifest)
            update_deploy_state "$dest" "$src_content"
            MANAGED_FILE_RESULT="verified"
            return 0
        fi

        # Content differs — check deploy state for auto-deploy eligibility
        local state_hash existing_hash
        state_hash=$(get_deploy_state_hash "$dest")
        if [ -n "$state_hash" ]; then
            existing_hash=$(get_content_hash "$existing")
            if [ "$existing_hash" = "$state_hash" ]; then
                # User didn't edit since last deploy → auto-deploy silently
                backup_file "$dest"
                printf '%s\n' "$src_content" > "$dest"
                update_deploy_state "$dest" "$src_content"
                log "Auto-deployed: $item_name (no local edits detected)"
                MANAGED_FILE_RESULT="updated"
                return 0
            fi
        fi

        # User edited AND source changed — backup + interactive review
        backup_file "$dest"
        local ancestor_content
        ancestor_content=$(get_deploy_shadow "$dest")
        # Bootstrap: seed shadow from current deployed content if empty
        if [ -z "$ancestor_content" ]; then
            log "Bootstrapping deploy shadow from existing: $(display_path "$dest")"
            ancestor_content="$existing"
        fi
        prompt_diff_review "$dest" "$src_content" "$adopt_label" "$existing" "$ancestor_content"
        case "$DIFF_REVIEW_RESULT" in
            adopt)
                MANAGED_FILE_RESULT="accept & adopt"
                return 0
                ;;
            skip)
                log_warn "Skipped: $item_name"
                MANAGED_FILE_RESULT="skipped"
                return 0
                ;;
            merge-adopt)
                src_content="$MERGED_CONTENT"
                printf '%s' "$src_content" > "$dest"
                update_deploy_state "$dest" "$src_content"
                log_ok "Updated (merge-adopt): $item_name"
                MANAGED_FILE_RESULT="accept & adopt"
                return 0
                ;;
            merge)
                src_content="$MERGED_CONTENT"
                ;;
        esac
        # overwrite or merge: write content to dest
        printf '%s\n' "$src_content" > "$dest"
        update_deploy_state "$dest" "$src_content"
        MANAGED_FILE_RESULT="updated"
        log_ok "Updated: $item_name -> $(display_path "$dest")"
    else
        # New file — create
        printf '%s\n' "$src_content" > "$dest"
        update_deploy_state "$dest" "$src_content"
        MANAGED_FILE_RESULT="created"
        log_ok "Created: $item_name -> $(display_path "$dest")"
    fi
}

# ---------------------------------------------------------------------------
# Deploy tracker: centralizes outcome counting and summary writing for
# loops that deploy multiple managed files (rules, skills, hooks).
# ---------------------------------------------------------------------------

# Reset all deploy tracker counters. Call before a deploy loop.
_DT_ADDED=0; _DT_UPDATED=0; _DT_VERIFIED=0
_DT_ACCEPTED=0; _DT_SKIPPED=0; _DT_PRESERVED=0
DEPLOY_TRACKER_TEXT=""

deploy_tracker_init() {
    _DT_ADDED=0; _DT_UPDATED=0; _DT_VERIFIED=0
    _DT_ACCEPTED=0; _DT_SKIPPED=0; _DT_PRESERVED=0
    DEPLOY_TRACKER_TEXT=""
}

# Record a single file outcome. Increments counter and writes DETAIL summary.
# Args: $1=outcome $2=tool_name $3=item_name
deploy_tracker_record() {
    local outcome="$1" tool_name="$2" item_name="$3"
    case "$outcome" in
        added|created) _DT_ADDED=$((_DT_ADDED + 1))
                   write_summary DETAIL "$tool_name" "added: $item_name" ;;
        updated)   _DT_UPDATED=$((_DT_UPDATED + 1))
                   write_summary DETAIL "$tool_name" "updated: $item_name" ;;
        "accept & adopt") _DT_ACCEPTED=$((_DT_ACCEPTED + 1))
                       write_summary DETAIL "$tool_name" "accept & adopt: $item_name" ;;
        skipped)   _DT_SKIPPED=$((_DT_SKIPPED + 1))
                   write_summary DETAIL "$tool_name" "skipped: $item_name" ;;
        verified)  _DT_VERIFIED=$((_DT_VERIFIED + 1)) ;;
        preserved) _DT_PRESERVED=$((_DT_PRESERVED + 1)) ;;
    esac
}

# Write aggregate summary for a deploy loop. Uses non-zero counts.
# Sets DEPLOY_TRACKER_TEXT for use in log lines.
# Args: $1=tool_name
deploy_tracker_summary() {
    local tool_name="$1"
    local parts=""
    [ "$_DT_ADDED" -gt 0 ]     && parts="$_DT_ADDED added"
    [ "$_DT_UPDATED" -gt 0 ]   && parts="${parts:+$parts, }$_DT_UPDATED updated"
    [ "$_DT_ACCEPTED" -gt 0 ]  && parts="${parts:+$parts, }$_DT_ACCEPTED accepted"
    [ "$_DT_VERIFIED" -gt 0 ]  && parts="${parts:+$parts, }$_DT_VERIFIED verified"
    [ -z "$parts" ] && parts="verified"
    DEPLOY_TRACKER_TEXT="$parts"

    if [ "$_DT_SKIPPED" -gt 0 ]; then
        write_summary WARN "$tool_name" "$_DT_SKIPPED skipped (user review)"
    else
        write_summary OK "$tool_name" "$parts"
    fi
}

# ---------------------------------------------------------------------------
# Repair broken uv tool environment (cross-platform)
# ---------------------------------------------------------------------------
# When `uv tool upgrade <tool>` fails with "missing a valid environment",
# find a working Python via `uv python find` (fallback: system python/python3)
# and reinstall with --force --python <path>.
# Returns 0 if repaired, 1 if not applicable or failed.
repair_uv_tool_env() {
    local tool_name="$1"
    local upgrade_output="${2:-}"

    if ! printf '%s\n' "$upgrade_output" | grep -q 'missing a valid environment'; then
        return 1
    fi

    log_warn "$tool_name uv environment is broken (Python removed?) -- repairing..."

    # Find a working Python -- uv's own Pythons first, then system
    local working_python=""
    local uv_python
    uv_python=$(uv python find 2>/dev/null) || true
    if [ -n "$uv_python" ] && [ -x "$uv_python" ]; then
        working_python="$uv_python"
    elif command -v python3 >/dev/null 2>&1; then
        working_python=$(command -v python3)
    elif command -v python >/dev/null 2>&1; then
        working_python=$(command -v python)
    fi

    if [ -z "$working_python" ]; then
        log_error "Cannot repair $tool_name -- no working Python found"
        return 1
    fi

    log "Repairing with: uv tool install --force --python $working_python $tool_name"
    local repair_output
    repair_output=$(uv tool install --force --python "$working_python" "$tool_name" 2>&1) || true
    printf '%s\n' "$repair_output" | while IFS= read -r line; do
        [ -n "$line" ] && log "$line"
    done

    if printf '%s\n' "$repair_output" | grep -qi 'error.*failed'; then
        log_error "$tool_name environment repair failed"
        return 1
    fi

    log_ok "Repaired $tool_name uv environment"
    return 0
}

# ---------------------------------------------------------------------------
# Parse CHANGED: lines from a node merge result and emit DETAIL summary entries.
# Usage: emit_merge_details "$MERGE_RESULT" "tool_name"
# Only processes lines prefixed with "CHANGED: " -- ignores status and other output.
# ---------------------------------------------------------------------------
emit_merge_details() {
    local merge_result="$1" tool_name="$2"
    local changed_keys
    changed_keys=$(echo "$merge_result" | perl -ne 'print if s/^CHANGED: //')
    if [ -n "$changed_keys" ]; then
        while IFS= read -r key_change; do
            log "  $key_change"
            write_summary DETAIL "$tool_name" "$key_change"
        done <<< "$changed_keys"
    fi
}

# ---------------------------------------------------------------------------
# JSON normalization for comparison (sorted keys, deterministic output)
# ---------------------------------------------------------------------------
# JavaScript JSON.stringify preserves insertion order, which may differ
# between runs or between PS1/bash variants writing the same file. Sorting
# keys before comparison ensures identical content produces identical JSON.
#
# SORT_KEYS_JS: minified sortKeys function for embedding in node -e blocks.
#   Usage: node -e "$SORT_KEYS_JS; ..."
#
# normalize_json: pipe-based wrapper for standalone use.
#   Usage: NORMALIZED=$(echo "$json_string" | normalize_json)
SORT_KEYS_JS='function sortKeys(o){if(o===null||typeof o!=="object")return o;if(Array.isArray(o))return o.map(sortKeys);var s={};Object.keys(o).sort().forEach(function(k){s[k]=sortKeys(o[k])});return s}'

normalize_json() {
    node -e "
        var input = require('fs').readFileSync('/dev/stdin', 'utf8');
        $SORT_KEYS_JS
        try {
            console.log(JSON.stringify(sortKeys(JSON.parse(input)), null, 2));
        } catch(e) {
            process.stderr.write('normalize_json: ' + e.message + '\n');
            process.exit(1);
        }
    "
}

# ---------------------------------------------------------------------------
# Go install provenance detection (macOS)
# Returns: "homebrew", "pkg-installer", "goenv", "manual", "none", or "unknown"
# ---------------------------------------------------------------------------
detect_go_provenance() {
    local go_path
    go_path=$(command -v go 2>/dev/null) || { echo "none"; return; }
    case "$go_path" in
        /opt/homebrew/*/go|/usr/local/Cellar/*/go)
            echo "homebrew" ;;
        /usr/local/go/bin/go)
            # Check if installed via macOS .pkg installer (pkgutil) or manual tarball
            if pkgutil --pkg-info=org.golang.go >/dev/null 2>&1; then
                echo "pkg-installer"
            else
                echo "manual"
            fi ;;
        */.goenv/*)
            echo "goenv" ;;
        *)
            echo "unknown" ;;
    esac
}

# ---------------------------------------------------------------------------
# Ensure GOPATH/bin is on PATH for current session
# Returns 0 if already on PATH, 1 if added (caller should warn re persistence)
# ---------------------------------------------------------------------------
ensure_gopath_bin_on_path() {
    local gopath_bin="${GOPATH:-$HOME/go}/bin"
    case ":$PATH:" in
        *":$gopath_bin:"*) return 0 ;;
    esac
    export PATH="$gopath_bin:$PATH"
    return 1
}

# ---------------------------------------------------------------------------
# Summary panel renderer
# ---------------------------------------------------------------------------
# Reads AITOOLS_SUMMARY_FILE, displays colored panel, cleans up.
# Silent no-op if file unset, missing, or empty.
show_summary() {
    local sfile="${AITOOLS_SUMMARY_FILE:-}"
    [ -n "$sfile" ] || return 0
    [ -f "$sfile" ] || return 0
    [ -s "$sfile" ] || { rm -f "$sfile"; return 0; }

    # Dedup by tool name: highest severity wins (ERROR > WARN > OK).
    # ACTIONs (empty tool name) are never deduped. DETAIL lines collected separately.
    # Output is pre-sorted: OK+details, WARN+details, ERROR+details, ACTIONs.
    local deduped
    deduped=$(perl -F'\|' -lane '
        BEGIN { %rank = (OK => 1, WARN => 2, ERROR => 3); }
        $cat = $F[0]; $tool = $F[1]; $det = join("|", @F[2..$#F]);
        if ($cat eq "DETAIL") {
            push @{$details{$tool}}, $det; next;
        }
        if ($cat eq "ACTION" || $tool eq "") {
            push @actions, $_; next;
        }
        $r = $rank{$cat} // 0;
        if (!exists $best{$tool}) {
            push @order, $tool;
            $best{$tool} = $cat; $detail{$tool} = $det;
        } elsif ($r > ($rank{$best{$tool}} // 0)) {
            $best{$tool} = $cat; $detail{$tool} = $det;
        }
        END {
            my (@ok, @warn, @err);
            for my $t (@order) {
                my @g = ("$best{$t}|$t|$detail{$t}",
                         map { "DETAIL|$t|$_" } @{$details{$t} // []});
                if    ($best{$t} eq "OK")    { push @ok,   @g }
                elsif ($best{$t} eq "WARN")  { push @warn, @g }
                elsif ($best{$t} eq "ERROR") { push @err,  @g }
            }
            print for @ok, @warn, @err, @actions;
        }
    ' "$sfile")

    # Single-pass display: Perl output is pre-sorted by severity.
    # DETAIL lines inherit the color of their preceding parent entry.
    echo ""
    echo "────────────────────────────────────────────────────────"
    local last_color="" first_action=true
    while IFS='|' read -r cat tool detail; do
        case "$cat" in
            OK)
                last_color='\033[32m'
                printf '\033[32m  [ok]  %-16s %s\033[0m\n' "$tool" "$detail"
                ;;
            WARN)
                last_color='\033[33m'
                printf '\033[33m  [!]   %-16s %s\033[0m\n' "$tool" "$detail"
                ;;
            ERROR)
                last_color='\033[31m'
                printf '\033[31m  [ERR] %-16s %s\033[0m\n' "$tool" "$detail"
                ;;
            DETAIL)
                printf '%b                          %s\033[0m\n' "$last_color" "$detail"
                ;;
            ACTION)
                if [ "$first_action" = true ]; then
                    echo ""
                    printf '\033[1;35m  ACTION REQUIRED -- run before tools are ready:\033[0m\n'
                    first_action=false
                fi
                printf '\033[1;35m  >>  %s\033[0m\n' "$detail"
                ;;
        esac
    done <<< "$deduped"
    echo "────────────────────────────────────────────────────────"

    # Preserve summary for log compliance checks
    if [ "${AITOOLS_PRESERVE_SUMMARY:-}" = "1" ]; then
        # cp may fail if log dir was cleaned up; non-blocking (summary already displayed)
        if ! cp "$sfile" "$LOG_DIR/last-summary.txt" 2>/dev/null; then
            printf 'warning: could not preserve summary file\n' >&2
        fi
    fi
    # Cleanup summary file (already displayed; rm -f ignores nonexistent files)
    rm -f "$sfile"
}

# ---------------------------------------------------------------------------
# Build prerequisite checking
# ---------------------------------------------------------------------------

# ensure_tool_on_path: Verify a tool is findable after installation.
# Tries: 1) command -v (current PATH), 2) hash -r (cache refresh),
# 3) known paths fallback (filesystem check + session PATH update).
# Usage: ensure_tool_on_path "nasm" "/usr/local/bin/nasm" "/opt/homebrew/bin/nasm"
# Returns 0 if tool is now on PATH, 1 otherwise.
ensure_tool_on_path() {
    local tool_name="$1"
    shift
    local known_paths=("$@")

    # Already on PATH?
    if command -v "$tool_name" >/dev/null 2>&1; then return 0; fi

    # Refresh command cache (picks up tools installed earlier in the same session)
    hash -r 2>/dev/null  # expected to succeed; some shells don't support it
    if command -v "$tool_name" >/dev/null 2>&1; then return 0; fi

    # Fallback: check known install locations on disk
    for kp in "${known_paths[@]}"; do
        if [ -x "$kp" ]; then
            local parent_dir
            parent_dir=$(dirname "$kp")
            export PATH="$parent_dir:$PATH"
            log "$tool_name found at $kp (added to session PATH)"
            return 0
        fi
    done
    return 1
}

# Check known build prerequisites for an ecosystem.
# Usage: check_build_prereqs "cargo"
#   Outputs missing prereq info to stdout (one per line: NAME|INSTALL_INSTRUCTION).
#   Returns 0 if all present, 1 if any missing.
check_build_prereqs() {
    local ecosystem="$1"
    local missing=0

    # Refresh shell command cache (picks up tools installed earlier in the same session)
    hash -r 2>/dev/null  # expected to succeed; some shells don't support it

    case "$ecosystem" in
        cargo)
            # NASM -- required by aws-lc-sys on x86_64
            if [ "$(uname -m)" = "x86_64" ] && ! command -v nasm >/dev/null 2>&1; then
                # Fallback: check known install locations
                if ensure_tool_on_path "nasm" /usr/local/bin/nasm /opt/homebrew/bin/nasm /usr/bin/nasm; then
                    : # Found via fallback -- ensure_tool_on_path already added to PATH
                else
                    echo "NASM|brew install nasm (macOS) or apt-get install nasm (Linux)"
                    missing=1
                fi
            fi
            # cmake -- required by some crates
            # Official: cmake.org/download lists pip, ZIP, MSI (not winget)
            # macOS: brew install cmake (user-level, no sudo)
            # Windows: uv tool install cmake (user-level, see reference/tool-evaluation-playbook.md)
            if ! command -v cmake >/dev/null 2>&1; then
                if ensure_tool_on_path "cmake" /usr/local/bin/cmake /opt/homebrew/bin/cmake /usr/bin/cmake /Applications/CMake.app/Contents/bin/cmake; then
                    : # Found via fallback
                else
                    echo "CMake|brew install cmake (macOS) / uv tool install cmake (Windows) -- see cmake.org/download"
                    missing=1
                fi
            fi
            ;;
        pip)
            # Add pip-specific prereqs here as discovered
            ;;
        go)
            # Add go-specific prereqs here as discovered
            ;;
    esac

    return $missing
}

# ---------------------------------------------------------------------------
# Build failure diagnosis
# ---------------------------------------------------------------------------

# Scan build output for known failure signatures.
# Usage: diagnose_build_failure "$output"
#   Prints "NAME|REMEDY" if a known signature is found.
#   Returns 0 if found, 1 if no match.
diagnose_build_failure() {
    local output="$1"

    # Table of known failure patterns -> remediation
    # Add new entries here when new build failures are discovered.
    local -a patterns=(
        "NASM command not found|NASM|brew install nasm / apt-get install nasm"
        "linker.*not found|Linker|Install build-essential (Linux) or Xcode CLI tools (macOS)"
        "cmake.*not found|CMake|brew install cmake / uv tool install cmake (see cmake.org/download)"
        "pkg-config.*not found|pkg-config|brew install pkg-config / apt-get install pkg-config"
        "Python\.h.*not found|Python headers|Install python3-dev or python3-devel"
        "openssl.*not found|OpenSSL|brew install openssl / apt-get install libssl-dev"
    )

    for entry in "${patterns[@]}"; do
        local pattern="${entry%%|*}"
        local rest="${entry#*|}"
        if printf '%s\n' "$output" | grep -qiE "$pattern"; then
            echo "$rest"
            return 0
        fi
    done
    return 1
}
logging_init "setup-user-hooks"

# --- OS guard ---
case "$(uname -s)" in
    MINGW*|MSYS*|CYGWIN*)
        log_error "This script is for macOS/Linux. On Windows, use ${SCRIPT_NAME}.ps1 instead."
        exit 1 ;;
esac

[ "$DRY_RUN" = "true" ] && log "[DRY RUN] Preview mode -- no files will be written"

# --- Require node for JSON manipulation ---
if ! command -v node &>/dev/null; then
    log_error "node required for JSON manipulation"
    exit 1
fi
# --- Deploy embedded hook scripts to ~/.claude/hooks/ ---
HOOKS_DIR="$HOME/.claude/hooks"
mkdir -p "$HOOKS_DIR"

if [ "$DRY_RUN" = "true" ]; then
    log "[DRY RUN] Would deploy hooks to $HOOKS_DIR"
else
cat > "$HOOKS_DIR/session-archive.sh" <<'__EMB_ARCHIVE__'
#!/usr/bin/env bash
# session-archive.sh — Claude Code SessionEnd hook
# Archives session transcript to user repo, then auto-commits and pushes.
#
# Baseline: Claude Code 2.1.51 -- hook schema (session_id, cwd, transcript_path)
# Hook input: JSON on stdin with session_id, cwd, transcript_path, etc.
# See reference/user-repo.md for the archiving pattern.
#
# Design decisions:
#   - Silent exit on any misconfiguration (hook must never break Claude Code)
#   - Auto-commit + push after copy (implements planning brief decision #1)
#   - Push is best-effort: warns on failure, never blocks SessionEnd
#   - git add <specific-file> only (never git add -A) to avoid committing
#     unrelated dotprofile changes
#   - Pure-bash JSON parsing (jq not guaranteed in hook environment)
#   - Uses transcript file birth time for date (session start), fallback to today
#   - Portable: macOS, Linux, Windows Git Bash (uname -s dispatch for stat)
#
# KPI definitions (aspirational until decision #32 ships):
#   - crossMachineVisibilityRate: % sessions archived + committed + pushed
#     within 5 min of session end (target: >=99%)
#   - archivePushFailureRate: push failures per week (target: <1)

set -euo pipefail

# Read hook input from stdin
INPUT=$(cat)

# --- Pure-bash JSON field extraction ---
# Extracts a top-level string value from JSON. Handles simple cases only.
json_field() {
    local json="$1" key="$2"
    local val
    val=$(printf '%s' "$json" \
        | grep -o "\"$key\"[[:space:]]*:[[:space:]]*\"[^\"]*\"" \
        | head -1 \
        | sed 's/.*"'"$key"'"[[:space:]]*:[[:space:]]*"//' \
        | sed 's/"$//')
    printf '%s' "$val"
}

SESSION_ID=$(json_field "$INPUT" "session_id")
CWD=$(json_field "$INPUT" "cwd")
TRANSCRIPT=$(json_field "$INPUT" "transcript_path")

# All three fields are required
if [ -z "$SESSION_ID" ] || [ -z "$CWD" ] || [ -z "$TRANSCRIPT" ]; then
    exit 0
fi

# Transcript file must exist
if [ ! -f "$TRANSCRIPT" ]; then
    exit 0
fi

# --- Read user repo path from aitools config ---
CONFIG_FILE="${HOME}/.aitools/config.json"
if [ ! -f "$CONFIG_FILE" ]; then
    exit 0  # aitools not configured
fi

USER_REPO=$(json_field "$(cat "$CONFIG_FILE")" "userRepoPath")

if [ -z "$USER_REPO" ] || [ ! -d "$USER_REPO" ]; then
    exit 0  # user repo not configured or missing
fi

# --- Derive project name ---
REPO_ROOT=$(cd "$CWD" 2>/dev/null && git rev-parse --show-toplevel 2>/dev/null || echo "")
if [ -n "$REPO_ROOT" ]; then
    PROJECT=$(basename "$REPO_ROOT")
else
    PROJECT=$(basename "$CWD" | tr 'A-Z' 'a-z' | sed 's/[^a-z0-9-]/-/g')
fi

# --- Derive date from transcript file creation time ---
if [ "$(uname -s)" = "Darwin" ]; then
    DATE=$(stat -f "%SB" -t "%Y-%m-%d" "$TRANSCRIPT" 2>/dev/null || date -u +%Y-%m-%d)
else
    # Linux: stat -c %W gives birth time (0 if unsupported), fallback to modify time
    BIRTH=$(stat -c "%W" "$TRANSCRIPT" 2>/dev/null || echo "0")
    if [ "$BIRTH" != "0" ] && [ -n "$BIRTH" ]; then
        DATE=$(date -u -d "@$BIRTH" +%Y-%m-%d 2>/dev/null || date -u +%Y-%m-%d)
    else
        DATE=$(date -u -d "@$(stat -c '%Y' "$TRANSCRIPT" 2>/dev/null)" +%Y-%m-%d 2>/dev/null || date -u +%Y-%m-%d)
    fi
fi

# --- Session ID prefix (first 8 chars) ---
PREFIX=$(printf '%s' "$SESSION_ID" | cut -c1-8)

# --- Target path ---
DEST_DIR="${USER_REPO}/sessions/${PROJECT}"
DEST_FILE="${DEST_DIR}/${DATE}_${PREFIX}.jsonl"

# Skip if already archived
if [ -f "$DEST_FILE" ]; then
    exit 0
fi

mkdir -p "$DEST_DIR"
cp "$TRANSCRIPT" "$DEST_FILE"

# --- Auto-commit and push to dotprofile repo (decision #1) ---
# Best-effort: git failures warn to stderr but never block SessionEnd.
# Uses specific file staging (not git add -A) to avoid committing
# unrelated dotprofile changes.
GIT_OK=true
if ! command -v git > /dev/null 2>&1; then
    GIT_OK=false
fi

if $GIT_OK; then
    # Compute path relative to user repo root for git add
    RELATIVE_PATH="sessions/${PROJECT}/${DATE}_${PREFIX}.jsonl"
    COMMIT_MSG="Archive session ${DATE}_${PREFIX} (${PROJECT})"

    # All git operations run inside the dotprofile repo
    if ! git -C "$USER_REPO" add "$RELATIVE_PATH" 2>/dev/null; then
        printf '[session-archive] warn: git add failed for %s\n' "$RELATIVE_PATH" >&2
        GIT_OK=false
    fi

    if $GIT_OK; then
        if ! git -C "$USER_REPO" commit -m "$COMMIT_MSG" 2>/dev/null; then
            printf '[session-archive] warn: git commit failed (nothing to commit?)\n' >&2
            GIT_OK=false
        fi
    fi

    if $GIT_OK; then
        # Pull --rebase first to handle concurrent sessions or remote changes
        git -C "$USER_REPO" pull --rebase 2>/dev/null || true
        if ! git -C "$USER_REPO" push 2>/dev/null; then
            printf '[session-archive] warn: git push failed (offline or remote ahead)\n' >&2
        fi
    fi
fi

# --- Log archive event to harness DB (OBSERVE mode) ---
# Additive: if harness-db.py is missing or fails, archive still succeeds.
PYTHON=""
if command -v python3 > /dev/null 2>&1; then
    PYTHON="python3"
elif command -v python > /dev/null 2>&1; then
    PYTHON="python"
fi

if [ -n "$PYTHON" ] && [ -n "$REPO_ROOT" ]; then
    HELPER=""
    if [ -f "$REPO_ROOT/scripts/harness-db.py" ]; then
        HELPER="$REPO_ROOT/scripts/harness-db.py"
    elif [ -f "$HOME/repos/aitools/scripts/harness-db.py" ]; then
        HELPER="$HOME/repos/aitools/scripts/harness-db.py"
    fi

    if [ -n "$HELPER" ] && "$PYTHON" -c "import sqlite3" 2>/dev/null; then
        "$PYTHON" "$HELPER" log \
            --session "$SESSION_ID" \
            --type sitrep \
            --agent "session-archive" \
            --message "Transcript archived and committed to ${DEST_FILE}" \
            2>/dev/null || true
    fi
fi
__EMB_ARCHIVE__
cat > "$HOOKS_DIR/standing-order-guard.sh" <<'__EMB_GUARD__'
#!/usr/bin/env bash
# standing-order-guard.sh — Claude Code PreToolUse hook
# Enforces standing orders by inspecting tool calls before execution.
#
# Currently enforces:
#   USO: Dedicated tools for file ops (Read/Edit/Write/Grep/Glob, not Bash)
#   USO: Scratch files for complex scripting (no long inline commands)
#   USO: Simple Bash commands only (no &&, ||, ;, $(...), backticks, globs in rm)
#
# Hook contract:
#   - Receives JSON on stdin (tool_name, tool_input.command, etc.)
#   - Exit 0 = allow
#   - Exit 2 = block (stderr becomes Claude's feedback)
#   - Must never crash or hang (would break Claude Code)
#
# Rollout mode (per-check):
#   MODE_AND="enforce"      — && : zero false positives confirmed, blocking
#   MODE_SUBSHELL="enforce" — $(): zero false positives confirmed, blocking
#   MODE_SCRATCH="enforce"  — scratch files: zero false positives confirmed, blocking
#   MODE_REST="observe"     — ||, ;, backticks: false positives exist or low sample count
#   See .claude/rules/hook-rollout.md for the observe-then-enforce practice.
#
# Design decisions:
#   - Pure-bash JSON parsing (jq not guaranteed in hook environment)
#   - Conservative matching: only flag clear violations, allow ambiguous cases
#   - Helpful feedback: tell Claude which tool to use instead
#   - Pipeline exemption: cat/head/tail in pipelines (cmd | ...) are allowed
#     because the Read tool cannot pipe output into other commands

set -euo pipefail

# --- Mode and logging ---
MODE_AND="enforce"      # &&  — zero false positives confirmed; blocking
MODE_SUBSHELL="enforce" # $() — zero false positives confirmed; blocking
MODE_SCRATCH="enforce" # scratch files — zero false positives confirmed; blocking
MODE_REST="observe"     # ||, ;, backticks — false positives or low sample; observe only

LOG_DIR="$HOME/.claude/hooks/logs"
LOG_FILE="$LOG_DIR/standing-order-guard.log"

# Ensure log directory exists (needed for observe logging; harmless in enforce-only runs)
mkdir -p "$LOG_DIR"

# violation() — dispatch based on per-check mode
# $1: message  $2: mode variable value (enforce or observe; defaults to MODE_REST)
# In enforce mode: write message to stderr, exit 2 (block)
# In observe mode: append to log file, exit 0 (allow)
violation() {
    local message="$1"
    local mode="${2:-$MODE_REST}"
    if [ "$mode" = "enforce" ]; then
        echo "$message" >&2
        exit 2
    else
        printf '%s [WOULD-BLOCK] %s | cmd: %s\n' \
            "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$message" "$COMMAND" \
            >> "$LOG_FILE"
        exit 0
    fi
}

INPUT=$(cat)

# --- Pure-bash JSON field extraction ---
# Same pattern as session-archive.sh. Handles simple top-level string values.
# Uses bash regex (zero external process forks) since this is a hot-path hook.
json_field() {
    local json="$1" key="$2"
    local pattern="\"${key}\"[[:space:]]*:[[:space:]]*\"([^\"]*)\""
    if [[ "$json" =~ $pattern ]]; then
        printf '%s' "${BASH_REMATCH[1]}"
    fi
}

# Extract tool_input.command — it's nested, so we need the command field
# from within tool_input. Since our JSON parser is simple, we can grep for
# the "command" key directly (it appears at the tool_input level).
COMMAND=$(json_field "$INPUT" "command")

# If no command found (shouldn't happen for Bash tool), allow
if [ -z "$COMMAND" ]; then
    exit 0
fi

# --- USO: Scratch files for complex scripting ---
# In JSON, newlines in strings are escaped as \n (literal two-char sequence).
# Count occurrences by measuring string length before/after removing \n sequences.
# This avoids grep exit-code issues with set -euo pipefail when no matches exist.
STRIPPED="${COMMAND//\\n/}"
CMD_LEN=${#COMMAND}
STRIPPED_LEN=${#STRIPPED}
NEWLINE_COUNT=$(( (CMD_LEN - STRIPPED_LEN) / 2 ))
# 5+ lines (4+ newlines) = too complex for inline. Write a temp file instead.
if [ "$NEWLINE_COUNT" -ge 4 ]; then
    LINE_COUNT=$((NEWLINE_COUNT + 1))
    violation "USO: Scratch files --: This command is ~${LINE_COUNT} lines long. Write it to a temp .sh or .ps1 file using the Write tool, execute with Bash, then clean up. USO: never inline long commands in the Bash tool." "$MODE_SCRATCH"
fi

# --- USO: Simple Bash commands only ---
# Block compound operators and command substitution that trigger permission prompts.
# Pipelines (|) are explicitly OK per the USO.
# Checked before the first-token allowlist because compound commands like
# `git tag && git push` have `git` as first token and would exit early.
# $() and backtick checks use raw INPUT (not COMMAND) because json_field
# truncates at \" — $(...) inside quoted arguments would be invisible.
case "$COMMAND" in
    *'&&'*) violation "USO: Simple Bash commands only --: Don't use '&&' to chain commands. Make separate Bash tool calls instead. For git in another repo, use 'git -C /path' instead of 'cd /path && git'." "$MODE_AND" ;;
    *'||'*) violation "USO: Simple Bash commands only --: Don't use '||' to chain commands. Make separate Bash tool calls instead." "$MODE_REST" ;;
    *';'*)
        # Exempt ; inside scripting-language arguments: pwsh -Command '...;...' and perl '...;...'
        # The ; is a language-internal statement separator, not a shell command separator.
        # perl: any invocation (perl -ne, -pe, -e, -E, etc.) may contain Perl semicolons.
        case "$COMMAND" in
            pwsh\ *|powershell\ *|perl\ *) ;;
            *) violation "USO: Simple Bash commands only --: Don't use ';' to chain commands. Make separate Bash tool calls instead." "$MODE_REST" ;;
        esac
        ;;
esac
case "$INPUT" in
    *'$('*) violation "USO: Simple Bash commands only --: Don't use '\$(...)' command substitution. For commit messages, write to a temp file with Write and use 'git commit -F'. For other values, compute in a prior step." "$MODE_SUBSHELL" ;;
    *'`'*)  violation "USO: Simple Bash commands only --: Don't use backtick command substitution. For commit messages, write to a temp file with Write and use 'git commit -F'. For other values, compute in a prior step." "$MODE_REST" ;;
esac

# --- USO: Dedicated tools for file operations ---
# Pattern: command starts with a file-op utility that has a dedicated tool.
# We check the first token of the command (before any arguments).
read -r FIRST_TOKEN _ <<< "$COMMAND"

# Allowlist: commands that look like file ops but are legitimate shell use.
# pwsh wrapping, git operations, npm/node, etc. are always OK.
case "$FIRST_TOKEN" in
    pwsh|powershell|git|npm|node|python*|pip*|cargo|rustup|brew|winget|choco)
        exit 0
        ;;
esac

# --- USO: Simple Bash commands only (glob in destructive operations) ---
# Glob patterns in rm can expand unexpectedly. Write a cleanup script instead.
case "$FIRST_TOKEN" in
    rm)
        case "$COMMAND" in
            *'*'*|*'?'*)
                violation "USO: Simple Bash commands only --: Don't use glob patterns (*, ?) with 'rm'. Write a cleanup script listing the specific files, execute it, then clean up the script."
                ;;
        esac
        ;;
esac

# Check for standalone file-reading commands (should use Read tool)
# Allow in pipelines (cmd | ...) — Read tool can't pipe output into other commands.
case "$FIRST_TOKEN" in
    cat)
        case "$COMMAND" in
            *\|*) ;;  # Pipeline — legitimate shell use
            *) violation "USO: Dedicated tools --: Use the Read tool instead of 'cat' to read files. The Read tool provides line numbers and handles large files better." ;;
        esac
        ;;
    head)
        case "$COMMAND" in
            *\|*) ;;
            *) violation "USO: Dedicated tools --: Use the Read tool with offset/limit parameters instead of 'head'. Example: Read with limit=20 for the first 20 lines." ;;
        esac
        ;;
    tail)
        case "$COMMAND" in
            *\|*) ;;
            *) violation "USO: Dedicated tools --: Use the Read tool with offset parameter instead of 'tail'. Example: Read with offset=100 to start from line 100." ;;
        esac
        ;;
esac

# Check for standalone file-search commands (should use Grep tool)
# Allow in pipelines — Grep tool can't pipe output into other commands.
case "$FIRST_TOKEN" in
    grep|rg|egrep|fgrep)
        case "$COMMAND" in
            *\|*) ;;  # Pipeline — legitimate shell use
            *) violation "USO: Dedicated tools --: Use the Grep tool instead of '$FIRST_TOKEN' to search file contents. The Grep tool supports regex, file filtering, and multiple output modes." ;;
        esac
        ;;
esac

# Check for file-finding commands (should use Glob tool)
# Allow in pipelines — Glob tool can't pipe output into other commands.
case "$FIRST_TOKEN" in
    find)
        case "$COMMAND" in
            *\|*) ;;  # Pipeline — legitimate shell use
            *) violation "USO: Dedicated tools --: Use the Glob tool instead of 'find' to locate files. Example: Glob with pattern '**/*.sh' instead of 'find . -name \"*.sh\"'." ;;
        esac
        ;;
    ls)
        # ls is borderline -- block when clearly used to list directory contents
        # for exploration (should use Glob or Bash 'ls' for quick checks).
        # Allow: ls is commonly used for quick verification before mkdir, etc.
        # Decision: allow ls, it's a gray area and commonly used in workflows.
        exit 0
        ;;
esac

# Check for file-editing commands (should use Edit tool)
# Allow in pipelines — Edit tool can't pipe output into other commands.
case "$FIRST_TOKEN" in
    sed)
        case "$COMMAND" in
            *\|*) ;;  # Pipeline — legitimate shell use
            *) violation "USO: Dedicated tools --: Use the Edit tool instead of 'sed' to modify files. For non-trivial string manipulation, use Perl (USO: Perl for string manipulation)." ;;
        esac
        ;;
    awk)
        case "$COMMAND" in
            *\|*) ;;  # Pipeline — legitimate shell use
            *) violation "USO: Dedicated tools --: Use the Read tool instead of 'awk' to process files. For string manipulation, use Perl (USO: Perl for string manipulation)." ;;
        esac
        ;;
esac

# Check for file-writing patterns (should use Write tool)
# These are harder to detect by first token alone. Check the full first line
# for redirection patterns that indicate file creation.
FIRST_LINE=$(printf '%s' "$COMMAND" | head -1)
case "$FIRST_LINE" in
    echo*\>*|printf*\>*)
        # echo/printf redirecting to a file
        violation "USO: Dedicated tools --: Use the Write tool instead of echo/printf redirection to create files. The Write tool handles encoding and permissions correctly."
        ;;
esac

# All checks passed — allow the command
exit 0
__EMB_GUARD__
cat > "$HOOKS_DIR/scratch-init.sh" <<'__EMB_SCRATCH__'
#!/usr/bin/env bash
# scratch-init.sh — Claude Code SessionStart hook
# Creates a unique session scratch directory, logs stale dirs, discovers
# unconsumed handoffs, and registers the session in the harness SQLite DB.
#
# Design decisions:
#   - Silent exit on errors (hook must never break Claude Code)
#   - Logs stale session dirs older than 24h (no auto-delete after 30-file loss)
#   - Writes session dir path to .scratch/.current-session for agents
#   - Uses session_id from CC hook input for deterministic dir names (R1, #53)
#   - Discovers handoffs at .aitools/channel/handoffs/ (R3, #53)
#   - Registers session in harness SQLite DB if harness-db.py is available
#   - SQLite integration is OBSERVE mode (log-only, never blocks)

set -euo pipefail

# --- Pure-bash JSON field extraction (same as harvest-session.sh) ---
json_field() {
    local json="$1" key="$2"
    local val
    val=$(printf '%s' "$json" \
        | grep -o "\"$key\"[[:space:]]*:[[:space:]]*\"[^\"]*\"" \
        | head -1 \
        | sed 's/.*"'"$key"'"[[:space:]]*:[[:space:]]*"//' \
        | sed 's/"$//')
    printf '%s' "$val"
}

# Read hook input from stdin (contains session_id, cwd, etc.)
INPUT=$(cat)
SESSION_ID=$(json_field "$INPUT" "session_id")

# Find project root (hooks run in cwd but we need the git root)
PROJECT_ROOT=$(git rev-parse --show-toplevel 2>/dev/null || echo "")
if [ -z "$PROJECT_ROOT" ]; then
    PROJECT_ROOT="$(pwd)"
fi

SCRATCH_DIR="$PROJECT_ROOT/.scratch"

# Ensure .scratch/ exists
mkdir -p "$SCRATCH_DIR"

# --- Log stale session dirs (older than 24h) ---
# These are from crashed or killed sessions where SessionEnd never fired.
# Previously rm -rf'd here, but that destroyed 30 unharvested artifacts
# (session Z1IhGrcgGO, 2026-03-21). Now we leave them for manual cleanup.
if [ -d "$SCRATCH_DIR" ]; then
    stale_count=$(find "$SCRATCH_DIR" -maxdepth 1 -name "session-*" -type d -mmin +1440 2>/dev/null | wc -l | tr -d ' ')
    if [ "$stale_count" -gt 0 ]; then
        printf 'Stale scratch dirs: %d (older than 24h, run cleanup manually)\n' "$stale_count"
    fi
fi

# --- Create fresh session dir ---
# Use session_id for deterministic dir name (fixes .current-session race
# condition for concurrent sessions — M4 AAR P3, verified UA-6).
# Fallback to mktemp if session_id is empty (defensive).
SESSION_PREFIX=""
if [ -n "$SESSION_ID" ]; then
    SESSION_PREFIX=$(printf '%s' "$SESSION_ID" | cut -c1-10)
    SESSION_DIR="$SCRATCH_DIR/session-$SESSION_PREFIX"
    mkdir -p "$SESSION_DIR"
else
    SESSION_DIR=$(mktemp -d "$SCRATCH_DIR/session-XXXXXXXXXX")
fi

# Write the path so agents and the SessionEnd hook can find it
printf '%s' "$SESSION_DIR" > "$SCRATCH_DIR/.current-session"

# --- Discover unconsumed handoffs (R3, issue #53) ---
HANDOFFS_DIR="$PROJECT_ROOT/.aitools/channel/handoffs"
if [ -d "$HANDOFFS_DIR" ]; then
    handoff_count=0
    latest_handoff=""
    for hf in "$HANDOFFS_DIR"/handoff*; do
        [ -f "$hf" ] || continue
        handoff_count=$((handoff_count + 1))
        latest_handoff="$hf"
    done
    if [ "$handoff_count" -gt 0 ]; then
        printf 'Handoff available: %s (%d total in %s)\n' \
            "$(basename "$latest_handoff")" "$handoff_count" "$HANDOFFS_DIR"
    fi
fi

# --- Register session in harness SQLite DB (OBSERVE mode) ---
# This is additive — if harness-db.py is missing or fails, session
# continues normally. SQLite integration never blocks SessionStart.
if [ -n "$SESSION_ID" ]; then
    PYTHON=""
    if command -v python3 > /dev/null 2>&1; then
        PYTHON="python3"
    elif command -v python > /dev/null 2>&1; then
        PYTHON="python"
    fi

    if [ -n "$PYTHON" ]; then
        # Look for harness-db.py in multiple locations
        HELPER=""
        if [ -f "$PROJECT_ROOT/scripts/harness-db.py" ]; then
            HELPER="$PROJECT_ROOT/scripts/harness-db.py"
        elif [ -f "$HOME/repos/aitools/scripts/harness-db.py" ]; then
            HELPER="$HOME/repos/aitools/scripts/harness-db.py"
        fi

        if [ -n "$HELPER" ] && "$PYTHON" -c "import sqlite3" 2>/dev/null; then
            # Initialize harness databases (creates if missing)
            "$PYTHON" "$HELPER" init 2>/dev/null || true
            # Register this session
            "$PYTHON" "$HELPER" session start --id "$SESSION_ID" 2>/dev/null || true
            printf 'Harness DB: session %s registered\n' "$SESSION_ID"
        fi
    fi
fi

# SessionStart stdout is added as context for Claude
printf 'Session scratch directory: %s\n' "$SESSION_DIR"
__EMB_SCRATCH__
cat > "$HOOKS_DIR/harvest-session.sh" <<'__EMB_HARVEST__'
#!/usr/bin/env bash
# harvest-session.sh — Claude Code SessionEnd hook
# Classifies session scratch contents, harvests artifacts, cleans up,
# audits the harvesting/ directory, marks session complete in harness DB,
# and exports DB to JSON for git carry-forward.
#
# Design decisions:
#   - Silent exit on errors (hook must never break Claude Code)
#   - Only harvests if project has a harvesting/ directory
#   - Classification by file extension (code/scripts -> artifact, logs/msgs -> ephemeral)
#   - Pure-bash JSON parsing (jq not guaranteed in hook environment)
#   - Manifest updates via node (already required by aitools)
#   - SQLite session end + export is additive (OBSERVE mode, never blocks)
#   - No rm -rf of session dirs (30-file-loss fix, session Z1IhGrcgGO, 2026-03-21)

set -euo pipefail

# Read hook input from stdin
INPUT=$(cat)

# --- Pure-bash JSON field extraction ---
json_field() {
    local json="$1" key="$2"
    local val
    val=$(printf '%s' "$json" \
        | grep -o "\"$key\"[[:space:]]*:[[:space:]]*\"[^\"]*\"" \
        | head -1 \
        | sed 's/.*"'"$key"'"[[:space:]]*:[[:space:]]*"//' \
        | sed 's/"$//')
    printf '%s' "$val"
}

SESSION_ID=$(json_field "$INPUT" "session_id")
CWD=$(json_field "$INPUT" "cwd")

# Session ID prefix for filenames (first 10 chars, matching scratch dir suffix)
SESSION_PREFIX=""
if [ -n "$SESSION_ID" ]; then
    SESSION_PREFIX=$(printf '%s' "$SESSION_ID" | cut -c1-10)
fi

# Find project root
PROJECT_ROOT=$(cd "$CWD" 2>/dev/null && git rev-parse --show-toplevel 2>/dev/null || echo "$CWD")
SCRATCH_DIR="$PROJECT_ROOT/.scratch"

# --- Find session scratch dir ---
# Try session_id-based dir first (new pattern), then .current-session (legacy)
SESSION_DIR=""
if [ -n "$SESSION_PREFIX" ] && [ -d "$SCRATCH_DIR/session-$SESSION_PREFIX" ]; then
    SESSION_DIR="$SCRATCH_DIR/session-$SESSION_PREFIX"
elif [ -f "$SCRATCH_DIR/.current-session" ]; then
    SESSION_DIR=$(cat "$SCRATCH_DIR/.current-session" 2>/dev/null || echo "")
fi

# If no session dir or it doesn't exist, nothing to do
if [ -z "$SESSION_DIR" ] || [ ! -d "$SESSION_DIR" ]; then
    # Still mark session as ended in DB even if no scratch dir
    _mark_session_end=true
else
    _mark_session_end=false
fi

# --- Check if project supports harvesting ---
HARVESTING_DIR="$PROJECT_ROOT/harvesting"
HAS_HARVESTING=false
if [ -d "$HARVESTING_DIR" ]; then
    HAS_HARVESTING=true
fi

# --- Handoff destination ---
HANDOFFS_DIR="$PROJECT_ROOT/.aitools/channel/handoffs"

# --- Classify and process session dir contents ---
TODAY=$(date -u +%Y-%m-%d)
HARVESTED=0
DELETED=0

if [ -n "$SESSION_DIR" ] && [ -d "$SESSION_DIR" ]; then
    for file in "$SESSION_DIR"/*; do
        [ -f "$file" ] || continue
        filename=$(basename "$file")

        # Classification by extension and name
        is_ephemeral=true
        case "$filename" in
            commit-msg*|*.log|*.tmp)
                is_ephemeral=true
                ;;
            *.py|*.sh|*.ps1|*.js|*.ts|*.go|*.rs|*.pl)
                is_ephemeral=false
                ;;
            *.json)
                # JSON: config/lock files are ephemeral, structured data is artifact
                case "$filename" in
                    package-lock*|node_modules*|*.config.json|tsconfig*) is_ephemeral=true ;;
                    *) is_ephemeral=false ;;
                esac
                ;;
            *.md)
                # Markdown: logs are ephemeral, research/analysis is artifact
                case "$filename" in
                    *log*|*output*|*dump*) is_ephemeral=true ;;
                    *) is_ephemeral=false ;;
                esac
                ;;
            *.yaml|*.yml|*.toml|*.csv|*.sql|*.html|*.txt)
                is_ephemeral=false
                ;;
            *)
                # Unknown extension: harvest with warning rather than silently delete
                is_ephemeral=false
                ;;
        esac

        if $is_ephemeral; then
            DELETED=$((DELETED + 1))
            continue
        fi

        # --- Route non-ephemeral files ---

        # Handoff files go to .aitools/channel/handoffs/ (dedicated location)
        is_handoff=false
        case "$filename" in
            handoff*) is_handoff=true ;;
        esac

        if $is_handoff; then
            # Auto-create handoffs dir if it doesn't exist
            if [ ! -d "$HANDOFFS_DIR" ]; then
                mkdir -p "$HANDOFFS_DIR" 2>/dev/null || true
            fi
        fi
        if $is_handoff && [ -d "$HANDOFFS_DIR" ]; then
            # Handoff: copy to handoffs/ with session ID
            handoff_dest="${HANDOFFS_DIR}/${TODAY}_session-${SESSION_PREFIX}_${filename}"
            cp "$file" "$handoff_dest" 2>/dev/null || true
            HARVESTED=$((HARVESTED + 1))
            continue
        fi

        # Auto-create harvesting/ on first harvest (F2 from issue #54)
        if ! $HAS_HARVESTING; then
            mkdir -p "$HARVESTING_DIR" 2>/dev/null
            if [ -d "$HARVESTING_DIR" ]; then
                HAS_HARVESTING=true
            fi
            # Create minimal manifest
            if command -v node >/dev/null 2>&1; then
                MANIFEST="$HARVESTING_DIR/harvest-manifest.json"
                node -e "
const fs = require('fs');
const f = process.argv[1];
if (!fs.existsSync(f)) {
    fs.writeFileSync(f, JSON.stringify({ meta: { schemaVersion: '1.0', lastAudit: null }, artifacts: {} }, null, 2) + '\n');
}
" "$MANIFEST" 2>/dev/null || true
            fi
            printf '[harvest] Created harvesting/ directory in %s\n' "$PROJECT_ROOT" >&2
        fi

        if $HAS_HARVESTING; then
            # Harvest: copy to harvesting/ with date + session ID prefix
            session_tag=""
            if [ -n "$SESSION_PREFIX" ]; then
                session_tag="session-${SESSION_PREFIX}_"
            fi
            dest_name="${TODAY}_${session_tag}${filename}"
            dest_path="$HARVESTING_DIR/$dest_name"

            # Avoid overwrites
            if [ -f "$dest_path" ]; then
                counter=1
                while [ -f "${HARVESTING_DIR}/${TODAY}_${counter}_${session_tag}${filename}" ]; do
                    counter=$((counter + 1))
                done
                dest_name="${TODAY}_${counter}_${session_tag}${filename}"
                dest_path="$HARVESTING_DIR/$dest_name"
            fi

            cp "$file" "$dest_path"

            # Update manifest if node is available
            MANIFEST="$HARVESTING_DIR/harvest-manifest.json"
            if command -v node >/dev/null 2>&1; then
                # Derive session reference
                session_ref=""
                if [ -n "$CWD" ]; then
                    project_name=$(basename "$PROJECT_ROOT")
                    session_ref="${project_name}/${TODAY}_${SESSION_PREFIX}"
                fi

                node -e "
const fs = require('fs');
const f = process.argv[1];
const name = process.argv[2];
const session = process.argv[3];
const desc = process.argv[4];
const today = process.argv[5];

let manifest = { meta: { schemaVersion: '1.0', lastAudit: null }, artifacts: {} };
try { manifest = JSON.parse(fs.readFileSync(f, 'utf8')); } catch {}

manifest.artifacts[name] = {
    harvested: today,
    session: session,
    description: 'Auto-harvested from session scratch',
    type: 'code',
    language: null,
    status: 'harvested',
    promotedTo: null,
    pruneAfter: new Date(Date.now() + 30*24*60*60*1000).toISOString().split('T')[0]
};

// Detect language from extension
const ext = name.split('.').pop();
const langMap = { py: 'python', sh: 'bash', ps1: 'powershell', js: 'javascript', ts: 'typescript', go: 'go', rs: 'rust', pl: 'perl', md: 'markdown' };
if (langMap[ext]) manifest.artifacts[name].language = langMap[ext];

fs.writeFileSync(f, JSON.stringify(manifest, null, 2) + '\n');
" "$MANIFEST" "$dest_name" "$session_ref" "$filename" "$TODAY" 2>/dev/null || true
            fi

            HARVESTED=$((HARVESTED + 1))
        fi
    done
fi

# --- Report harvest results (F4 from issue #54) ---
if [ "$HARVESTED" -gt 0 ] || [ "$DELETED" -gt 0 ]; then
    printf '[harvest] Session %s: %d artifacts harvested, %d ephemeral skipped\n' \
        "${SESSION_PREFIX:-unknown}" "$HARVESTED" "$DELETED" >&2
fi

# --- Clear session pointer (leave session dir intact) ---
# Previously rm -rf'd $SESSION_DIR here, but if harvest partially failed
# or classification missed files, they became unrecoverable (see 30-file
# loss incident, session Z1IhGrcgGO, 2026-03-21). Session dirs accumulate
# in .scratch/ and are logged as stale by scratch-init.sh on next session.
rm -f "$SCRATCH_DIR/.current-session"

# --- Audit harvesting/ (prune stale) ---
if $HAS_HARVESTING && command -v node >/dev/null 2>&1; then
    MANIFEST="$HARVESTING_DIR/harvest-manifest.json"
    if [ -f "$MANIFEST" ]; then
        node -e "
const fs = require('fs');
const path = require('path');
const f = process.argv[1];
const dir = process.argv[2];

let manifest;
try { manifest = JSON.parse(fs.readFileSync(f, 'utf8')); } catch { process.exit(0); }

const today = new Date();
let pruned = 0;

for (const [name, entry] of Object.entries(manifest.artifacts)) {
    if (entry.status === 'promoted' || entry.status === 'pruned') continue;

    // Check prune date
    if (entry.pruneAfter) {
        const pruneDate = new Date(entry.pruneAfter);
        if (today > pruneDate) {
            // Check git references before pruning
            const { execSync } = require('child_process');
            let refs = 0;
            try {
                const out = execSync('git log --all --oneline -- ' + path.join(dir, name), { encoding: 'utf8', timeout: 5000 });
                refs = out.trim().split('\n').filter(l => l).length;
            } catch {}

            if (refs === 0) {
                // Mark as pruned in manifest but do NOT delete the file.
                // Previous auto-deletion destroyed artifacts before review.
                // Files accumulate in harvesting/ for manual cleanup.
                entry.status = 'pruned';
                pruned++;
            } else {
                // Has references — promote to candidate
                entry.status = 'candidate';
            }
        }
    }
}

manifest.meta.lastAudit = today.toISOString().split('T')[0];
fs.writeFileSync(f, JSON.stringify(manifest, null, 2) + '\n');
" "$MANIFEST" "$HARVESTING_DIR" 2>/dev/null || true
    fi
fi

# --- Mark session complete in harness SQLite DB (OBSERVE mode) ---
# Additive: if harness-db.py is missing or fails, harvest still succeeds.
if [ -n "$SESSION_ID" ]; then
    PYTHON=""
    if command -v python3 > /dev/null 2>&1; then
        PYTHON="python3"
    elif command -v python > /dev/null 2>&1; then
        PYTHON="python"
    fi

    if [ -n "$PYTHON" ]; then
        HELPER=""
        if [ -f "$PROJECT_ROOT/scripts/harness-db.py" ]; then
            HELPER="$PROJECT_ROOT/scripts/harness-db.py"
        elif [ -f "$HOME/repos/aitools/scripts/harness-db.py" ]; then
            HELPER="$HOME/repos/aitools/scripts/harness-db.py"
        fi

        if [ -n "$HELPER" ] && "$PYTHON" -c "import sqlite3" 2>/dev/null; then
            # Mark session as ended
            "$PYTHON" "$HELPER" session end --id "$SESSION_ID" 2>/dev/null || true
            # Export DB to JSON for git carry-forward
            "$PYTHON" "$HELPER" export --format json --session "$SESSION_ID" 2>/dev/null || true
            printf '[harness-db] Session %s ended, JSON exported\n' "$SESSION_ID" >&2
        fi
    fi
fi

exit 0
__EMB_HARVEST__
cat > "$HOOKS_DIR/sh-file-fixup.sh" <<'__EMB_SHFIXUP__'
#!/usr/bin/env bash
# sh-file-fixup.sh — Claude Code PostToolUse hook for Write and Edit
# Auto-fixes .sh files after creation/modification:
#   - CRLF → LF line endings (Write tool on macOS can produce CRLF)
#   - chmod +x on disk (Write tool creates 100644)
#   - git update-index --chmod=+x (if tracked with wrong mode)
#
# Eliminates the recurring manual fixup cycle that interrupts every commit
# involving .sh files. See reference/framework-incident-investigation.md.
#
# Hook contract:
#   - PostToolUse on Write|Edit (runs AFTER the tool completes)
#   - Receives JSON on stdin with tool_input.file_path
#   - Exit 0 always (PostToolUse must never block)
#   - Stderr feedback is shown to Claude

set -euo pipefail

# Read JSON from stdin
input=$(cat)

# Extract file_path from tool_input (pure-bash, no jq dependency)
file_path=""
if [[ "$input" =~ \"file_path\"[[:space:]]*:[[:space:]]*\"([^\"]+)\" ]]; then
    file_path="${BASH_REMATCH[1]}"
fi

# Only act on .sh files
[ -n "$file_path" ] || exit 0
[[ "$file_path" == *.sh ]] || exit 0
[ -f "$file_path" ] || exit 0

fixed=""

# Fix CRLF → LF
if perl -ne 'exit 1 if /\r/' "$file_path" 2>/dev/null; then
    : # no CRLF found
else
    perl -pi -e 's/\r$//' "$file_path"
    fixed="${fixed}CRLF->LF "
fi

# Fix executable bit on disk
if [ ! -x "$file_path" ]; then
    chmod +x "$file_path"
    fixed="${fixed}+x "
fi

# Fix git index executable bit (if inside a git work tree)
dir=$(dirname "$file_path")
if git -C "$dir" rev-parse --is-inside-work-tree >/dev/null 2>&1; then
    mode=$(git -C "$dir" ls-files -s "$file_path" 2>/dev/null | cut -c1-6)
    if [ "$mode" = "100644" ]; then
        git update-index --chmod=+x "$file_path" 2>/dev/null || true
        fixed="${fixed}git+x "
    fi
fi

# Report what was fixed (stderr → shown to Claude as feedback)
if [ -n "$fixed" ]; then
    echo "sh-file-fixup: $(basename "$file_path") — fixed: ${fixed% }" >&2
fi

exit 0
__EMB_SHFIXUP__
cat > "$HOOKS_DIR/surfacing-duty-stop.sh" <<'__EMB_SURFACING__'
#!/usr/bin/env bash
# surfacing-duty-stop.sh — Claude Code Stop hook (command type)
# Surfaces duty reminders via stderr feedback after agent responses.
#
# Fires after every agent response. As a command-type Stop hook,
# stderr output is shown to the agent as feedback on its next turn.
#
# Two functions:
#   1. Periodic reminder: every 30+ minutes, remind about surfacing duty
#   2. Incident-acknowledgment detection: if agent said "incident" or "pre-existing"
#      without invoking /incident or writing TODO(incident):, prompt them to file
#
# Hook contract:
#   - Stop hook, command type (stderr → shown to agent as feedback)
#   - Exit 0 = allow, Exit 2 = block (we always allow)
#   - Must be fast (<50ms) — fires on every agent turn
#   - Must never crash or hang

set -euo pipefail

# Read JSON from stdin
input=$(cat)

# Extract session_id and transcript_path
session_id=""
transcript_path=""
if [[ "$input" =~ \"session_id\"[[:space:]]*:[[:space:]]*\"([^\"]+)\" ]]; then
    session_id="${BASH_REMATCH[1]}"
fi
if [[ "$input" =~ \"transcript_path\"[[:space:]]*:[[:space:]]*\"([^\"]+)\" ]]; then
    transcript_path="${BASH_REMATCH[1]}"
fi

# Need transcript to scan
[ -n "$transcript_path" ] && [ -f "$transcript_path" ] || exit 0

reminders=""

# --- 1. Periodic surfacing duty reminder ---
# Check session age via transcript file birth time.
# Inject reminder every 30 minutes (tracked via marker file).
if [ -n "$session_id" ]; then
    marker_dir="/tmp/aitools-surfacing-$session_id"
    mkdir -p "$marker_dir" 2>/dev/null || true
    marker="$marker_dir/last-reminder"
    now=$(date +%s)
    inject_reminder=false

    if [ ! -f "$marker" ]; then
        # First check: only inject if session is >30 min old
        # Use transcript modification time as proxy for session start
        if [ -f "$transcript_path" ]; then
            # Platform dispatch: macOS BSD stat vs GNU stat (Linux/Git Bash)
            # See session-archive.sh:68 for the canonical pattern
            if [ "$(uname -s)" = "Darwin" ]; then
                file_mod=$(stat -f %m "$transcript_path" 2>/dev/null || echo "$now")
            else
                file_mod=$(stat -c %Y "$transcript_path" 2>/dev/null || echo "$now")
            fi
            age=$(( now - file_mod ))
            # Transcript gets modified constantly; use birth time if available
            if [ "$(uname -s)" = "Darwin" ]; then
                file_birth=$(stat -f %B "$transcript_path" 2>/dev/null || echo "$file_mod")
            else
                # GNU stat: %W = birth time (0 if unsupported), fallback to mod time
                _birth=$(stat -c %W "$transcript_path" 2>/dev/null || echo "0")
                if [ "$_birth" != "0" ] && [ -n "$_birth" ]; then
                    file_birth="$_birth"
                else
                    file_birth="$file_mod"
                fi
            fi
            session_age=$(( now - file_birth ))
            if [ "$session_age" -gt 1800 ]; then
                inject_reminder=true
            fi
        fi
    else
        last=$(cat "$marker")
        elapsed=$(( now - last ))
        if [ "$elapsed" -gt 1800 ]; then
            inject_reminder=true
        fi
    fi

    if [ "$inject_reminder" = "true" ]; then
        echo "$now" > "$marker"
        reminders="${reminders}Surfacing duty check: Have you found any incidents or ambiguities this session? File via /incident or leave a TODO(incident): comment. "
    fi
fi

# --- 2. Incident-acknowledgment detection ---
# Scan the last assistant message for incident-acknowledgment language
# without a corresponding /incident invocation or TODO(incident): marker.
#
# Suppression: if incidents.json was modified in the last 30 minutes,
# an incident was recently filed — suppress to avoid false positives when the
# agent is still discussing the incident after filing it.

_suppress_incident_check=false

# Check incidents.json modification time (cross-platform stat)
_incidents_file=""
if [ -n "${AITOOLS_REPO_PATH:-}" ]; then
    _incidents_file="$AITOOLS_REPO_PATH/reference/incidents.json"
elif [ -f "$HOME/repos/aitools/reference/incidents.json" ]; then
    _incidents_file="$HOME/repos/aitools/reference/incidents.json"
fi
if [ -n "$_incidents_file" ] && [ -f "$_incidents_file" ]; then
    # Platform dispatch: macOS BSD stat vs GNU stat (Linux/Git Bash)
    if [ "$(uname -s)" = "Darwin" ]; then
        _incidents_mod=$(stat -f %m "$_incidents_file" 2>/dev/null || echo "0")
    else
        _incidents_mod=$(stat -c %Y "$_incidents_file" 2>/dev/null || echo "0")
    fi
    _now_epoch=$(date +%s)
    _incidents_age=$(( _now_epoch - _incidents_mod ))
    if [ "$_incidents_age" -lt 1800 ]; then
        _suppress_incident_check=true
    fi
fi

if [ "$_suppress_incident_check" = "false" ]; then
    # Read only the last ~100 lines of transcript for speed.
    last_chunk=$(tail -100 "$transcript_path" 2>/dev/null || true)

    if [ -n "$last_chunk" ]; then
        # Check for incident-acknowledgment phrases
        has_incident_language=false
        if echo "$last_chunk" | grep -qiE "pre-existing incident|known incident|that.s an incident|existing incident|there.s an incident|incident I noticed|incident we found|pre-existing gap|known gap|that.s a gap|existing gap|there.s a gap|gap I noticed|gap we found" 2>/dev/null; then
            has_incident_language=true
        fi

        # Check if /incident was invoked or TODO(incident): was written in same chunk
        has_filing=false
        if echo "$last_chunk" | grep -qE '/incident|TODO\(incident\)|incidents\.json' 2>/dev/null; then
            has_filing=true
        fi

        if [ "$has_incident_language" = "true" ] && [ "$has_filing" = "false" ]; then
            reminders="${reminders}You acknowledged an incident but did not file it. Per surfacing duty (.claude/rules/incident-governance.md): invoke /incident now, or write TODO(incident): in the current file if mid-task."
        fi
    fi
fi

# Output reminders (if any) to stderr (shown to agent as feedback).
if [ -n "$reminders" ]; then
    printf '%s' "$reminders" >&2
fi

exit 0
__EMB_SURFACING__
cat > "$HOOKS_DIR/glossary-skill-guard.sh" <<'__EMB_GLOSSARY__'
#!/usr/bin/env bash
# glossary-skill-guard.sh — Detection layer for governed data access
# Fires on Read/Grep of glossary files, reminds agent to use /glossary skill
# Part of the governed data access framework.
# See reference/framework-governed-data-access.md

set -euo pipefail

INPUT=$(cat)
FILE_PATH=$(echo "$INPUT" | perl -ne 'print $1 if /"file_path"\s*:\s*"([^"]*)"/')
PATTERN_PATH=$(echo "$INPUT" | perl -ne 'print $1 if /"path"\s*:\s*"([^"]*)"/')

TARGET="${FILE_PATH:-$PATTERN_PATH}"

case "$TARGET" in
    *glossary.json|*glossary.md)
        # hookSpecificOutput JSON goes to stdout (structured hook response)
        echo '{"hookSpecificOutput":{"additionalContext":"You are reading glossary files directly. Use /glossary skill instead — it provides the governed process for checking definitions, adding terms, and resolving ambiguities. Reading the file bypasses that process."}}'
        ;;
esac
exit 0
__EMB_GLOSSARY__
cat > "$HOOKS_DIR/block-claude-code-guide.sh" <<'__EMB_BLOCKGUIDE__'
#!/usr/bin/env bash
# block-claude-code-guide.sh — Claude Code PreToolUse hook
# Blocks the built-in claude-code-guide subagent (Haiku model) and
# injects corrective harness context so the agent can proceed with
# accurate information without needing the subagent.
#
# Hook contract:
#   - Fires on PreToolUse for the Agent tool
#   - Receives JSON on stdin (tool_input.subagent_type, etc.)
#   - Exit 0 with no output = allow (all other agent types)
#   - Exit 0 with JSON stdout = deny with corrective context
#
# See: https://github.com/anthropics/claude-code/issues/34730

set -euo pipefail

INPUT=$(cat)

# Extract subagent_type from tool_input using bash regex (no jq dependency)
SUBAGENT_TYPE=""
pattern='"subagent_type"[[:space:]]*:[[:space:]]*"([^"]*)"'
if [[ "$INPUT" =~ $pattern ]]; then
    SUBAGENT_TYPE="${BASH_REMATCH[1]}"
fi

if [ "$SUBAGENT_TYPE" = "claude-code-guide" ]; then
    # Return JSON deny with corrective context.
    # permissionDecisionReason is shown to Claude (not the user) on deny,
    # so it serves as injected harness knowledge.
    cat <<'HOOKJSON'
{
  "hookSpecificOutput": {
    "hookEventName": "PreToolUse",
    "permissionDecision": "deny",
    "permissionDecisionReason": "claude-code-guide subagent is DENIED. It is a Haiku-based built-in that returns inaccurate schema information — it caused a production incident where all hooks were disabled (issue #34730). DO NOT retry this call.\n\nFor Claude Code documentation (hooks, settings, permissions, subagents, MCP), use the chrome-devtools skill to navigate to the .md pages at code.claude.com/docs/en/*.md and read the rendered content. Key pages:\n  - Hooks: code.claude.com/docs/en/hooks.md\n  - Permissions: code.claude.com/docs/en/permissions.md\n  - Sub-agents: code.claude.com/docs/en/sub-agents.md\n  - Settings: code.claude.com/docs/en/settings.md\n  - MCP: code.claude.com/docs/en/mcp.md\n\nQuick reference — hook type schemas:\n  type: \"command\" requires: command (string, shell command to execute)\n  type: \"prompt\"  requires: prompt (string, static LLM prompt text)\n  type: \"http\"    requires: url (string, endpoint URL)\n  type: \"agent\"   requires: prompt (string, task for subagent)\n\nNever mix these — a command-type hook with a prompt field or a prompt-type hook with a command field will break settings.json validation and disable ALL hooks."
  }
}
HOOKJSON
    exit 0
fi

exit 0
__EMB_BLOCKGUIDE__
cat > "$HOOKS_DIR/tool-ops-session-audit.sh" <<'__EMB_TOOLOPS__'
#!/usr/bin/env bash
# tool-ops-session-audit.sh — SessionEnd hook
# Reads tool-ops.json, runs quick verifications on audit-mode capabilities,
# logs drift and KPIs to tool-ops-audit.jsonl.
#
# Hook contract:
#   - SessionEnd hook, command type
#   - Always exit 0 (advisory — never block session end)
#   - Must handle missing files gracefully
#   - No jq dependency — uses grep/regex for JSON parsing

set -euo pipefail

# Read JSON from stdin (SessionEnd provides session_id, etc.)
input=$(cat)
session_id=""
if [[ "$input" =~ \"session_id\"[[:space:]]*:[[:space:]]*\"([^\"]+)\" ]]; then
    session_id="${BASH_REMATCH[1]}"
fi

# Find tool-ops.json
tool_ops=""
if [ -n "${AITOOLS_REPO_PATH:-}" ] && [ -f "$AITOOLS_REPO_PATH/reference/tool-ops.json" ]; then
    tool_ops="$AITOOLS_REPO_PATH/reference/tool-ops.json"
elif [ -f "$HOME/repos/aitools/reference/tool-ops.json" ]; then
    tool_ops="$HOME/repos/aitools/reference/tool-ops.json"
fi
# No tool-ops.json — nothing to audit
[ -n "$tool_ops" ] || exit 0

# Ensure log directory (exit silently if we cannot create it)
log_dir="$HOME/.claude/hooks/logs"
mkdir -p "$log_dir" 2>/dev/null || exit 0  # non-critical — exit clean if mkdir fails
log_file="$log_dir/tool-ops-audit.jsonl"
timestamp=$(date -u +%Y-%m-%dT%H:%M:%SZ)

# --- Contract tests (mock-json-pipe verifications) ---
# Run verification cases from tool-ops.json against deployed hook scripts.
# For each tool with a verifications array, pipe mock input to the target
# hook and check exit code + stdout against expected values.

drift_count=0
test_pass=0
test_fail=0

# Find hook scripts directory
hooks_dir="$HOME/.claude/hooks"

# Verify block-claude-code-guide.sh if deployed
guide_hook="$hooks_dir/block-claude-code-guide.sh"
if [ -f "$guide_hook" ]; then
    # Test 1: Should deny claude-code-guide subagent
    test_input='{"tool_name":"Agent","tool_input":{"subagent_type":"claude-code-guide"}}'
    # Capture output; ignore non-zero exit (should not happen but guard against it)
    test_output=$(echo "$test_input" | bash "$guide_hook" 2>/dev/null) || true  # hook may fail in unusual env — don't abort audit
    if echo "$test_output" | grep -q 'permissionDecision.*deny' 2>/dev/null; then  # grep stderr suppressed — pattern match only
        test_pass=$((test_pass + 1))
    else
        test_fail=$((test_fail + 1))
    fi

    # Test 2: Should allow Explore subagent (no deny output)
    test_input='{"tool_name":"Agent","tool_input":{"subagent_type":"Explore"}}'
    test_output=$(echo "$test_input" | bash "$guide_hook" 2>/dev/null) || true  # same guard as above
    if [ -z "$test_output" ]; then
        # Empty output = allowed (correct behavior)
        test_pass=$((test_pass + 1))
    else
        test_fail=$((test_fail + 1))
    fi
fi

# --- Drift detection: deny rules vs deployed settings ---
settings_file="$HOME/.claude/settings.json"
if [ -f "$settings_file" ] && [ -f "$guide_hook" ]; then
    # Check that block-claude-code-guide.sh is registered in settings.json PreToolUse
    if ! grep -q 'block-claude-code-guide\.sh' "$settings_file" 2>/dev/null; then  # grep stderr suppressed — file may be unreadable
        drift_count=$((drift_count + 1))
    fi
fi

# --- Version dep staleness check ---
# Look for the tool-ops reference doc and count items needing attention
ops_ref=""
if [ -n "${AITOOLS_REPO_PATH:-}" ] && [ -f "$AITOOLS_REPO_PATH/reference/tool-ops-claude-code.md" ]; then
    ops_ref="$AITOOLS_REPO_PATH/reference/tool-ops-claude-code.md"
elif [ -f "$HOME/repos/aitools/reference/tool-ops-claude-code.md" ]; then
    ops_ref="$HOME/repos/aitools/reference/tool-ops-claude-code.md"
fi

stale_deps=0
if [ -n "$ops_ref" ]; then
    # Count lines mentioning CRITICAL that also mention "Last verified" — heuristic for stale items
    # grep -c returns exit 1 on no match; capture in subshell to prevent set -e abort
    stale_deps=$(grep -c 'CRITICAL.*Last verified' "$ops_ref" 2>/dev/null || true)  # stderr suppressed — file may be unreadable
    # Ensure numeric — default to 0 if empty or non-numeric
    if ! [[ "$stale_deps" =~ ^[0-9]+$ ]]; then stale_deps=0; fi
fi

# --- Emit results ---
printf '{"timestamp":"%s","session_id":"%s","test_pass":%d,"test_fail":%d,"drift_count":%d,"stale_deps":%d}\n' \
    "$timestamp" "$session_id" "$test_pass" "$test_fail" "$drift_count" "$stale_deps" \
    >> "$log_file"

exit 0
__EMB_TOOLOPS__
cat > "$HOOKS_DIR/dashboard-serve.sh" <<'__EMB_DASHBOARD__'
#!/usr/bin/env bash
# dashboard-serve.sh -- Claude Code SessionStart hook
# Delegates to `aitools dashboard --background` for dashboard lifecycle.
#
# The CLI owns estimation discovery, PID management, port detection, and
# server launch. This hook is a thin dispatcher that extracts project
# root from the hook input and delegates.
#
# Hook contract:
#   - SessionStart hook, command type
#   - stdout is added as context for Claude
#   - Must be fast (<100ms for detection; server starts async)
#   - Must never crash or hang (silent exit on errors)

set -euo pipefail

# Read hook input from stdin (contains session_id, cwd, etc.)
INPUT=$(cat)

# Extract cwd from hook input
cwd=""
if [[ "$INPUT" =~ \"cwd\"[[:space:]]*:[[:space:]]*\"([^\"]+)\" ]]; then
    cwd="${BASH_REMATCH[1]}"
fi

# Find project root
PROJECT_ROOT=""
if [ -n "$cwd" ]; then
    PROJECT_ROOT=$(cd "$cwd" 2>/dev/null && git rev-parse --show-toplevel 2>/dev/null || echo "$cwd")
else
    PROJECT_ROOT=$(git rev-parse --show-toplevel 2>/dev/null || pwd)
fi

# Find aitools CLI
AITOOLS=""
if command -v aitools >/dev/null 2>&1; then
    AITOOLS="aitools"
elif [ -f "$HOME/.local/bin/aitools" ]; then
    AITOOLS="$HOME/.local/bin/aitools"
fi

if [ -n "$AITOOLS" ]; then
    # Delegate to CLI -- it handles everything
    cd "$PROJECT_ROOT" 2>/dev/null || true
    "$AITOOLS" dashboard --background --project-root "$PROJECT_ROOT" 2>/dev/null || true
else
    # Fallback: direct launch if aitools CLI not installed
    # This preserves functionality during initial setup before first `aitools install`
    PYTHON=""
    if command -v python3 >/dev/null 2>&1; then
        PYTHON="python3"
    elif command -v python >/dev/null 2>&1; then
        PYTHON="python"
    fi
    [ -n "$PYTHON" ] || exit 0

    GENERATOR=""
    if [ -f "$HOME/repos/aitools/scripts/generate-dashboard.py" ]; then
        GENERATOR="$HOME/repos/aitools/scripts/generate-dashboard.py"
    elif [ -f "$PROJECT_ROOT/scripts/generate-dashboard.py" ]; then
        GENERATOR="$PROJECT_ROOT/scripts/generate-dashboard.py"
    fi
    [ -n "$GENERATOR" ] || exit 0

    # Find estimate (simplified -- CLI has full search logic)
    ESTIMATE=""
    if [ -f "$PROJECT_ROOT/.aitools/channel/running-estimate.json" ]; then
        ESTIMATE="$PROJECT_ROOT/.aitools/channel/running-estimate.json"
    fi
    if [ -z "$ESTIMATE" ] && [ -d "$PROJECT_ROOT/.scratch" ]; then
        for dir in "$PROJECT_ROOT"/.scratch/session-*/; do
            [ -d "$dir" ] || continue
            for est in "$dir"/*running-estimate*.json; do
                [ -f "$est" ] || continue
                ESTIMATE="$est"
                break 2
            done
        done
    fi
    [ -n "$ESTIMATE" ] || exit 0

    PORT=8411
    PID_DIR="$PROJECT_ROOT/.aitools"
    mkdir -p "$PID_DIR" 2>/dev/null || PID_DIR="/tmp"
    PID_FILE="$PID_DIR/.dashboard-pid"

    # Check if already running
    if [ -f "$PID_FILE" ]; then
        old_pid=$(cat "$PID_FILE" 2>/dev/null || echo "")
        if [ -n "$old_pid" ] && kill -0 "$old_pid" 2>/dev/null; then
            printf 'Dashboard: http://localhost:%d/\n' "$PORT"
            exit 0
        fi
        rm -f "$PID_FILE"
    fi

    nohup "$PYTHON" "$GENERATOR" --estimate "$ESTIMATE" --serve --port "$PORT" \
        >/dev/null 2>&1 &
    SERVER_PID=$!
    disown "$SERVER_PID" 2>/dev/null || true
    printf '%d' "$SERVER_PID" > "$PID_FILE"
    sleep 0.3
    if kill -0 "$SERVER_PID" 2>/dev/null; then
        printf 'Dashboard: http://localhost:%d/\n' "$PORT"
    else
        rm -f "$PID_FILE"
    fi
fi

exit 0
__EMB_DASHBOARD__
cat > "$HOOKS_DIR/estimate-refresh-stop.sh" <<'__EMB_ESTIMREFRESH__'
#!/usr/bin/env bash
# estimate-refresh-stop.sh -- Claude Code Stop hook (command type)
# Combined Lagebeurteilung reminder + running estimate freshness tracker.
#
# Two functions:
#   1. Auto-track turn count via marker file (mechanical, no judgment)
#   2. At context threshold (estimated from turn count), inject
#      Lagebeurteilung reminder to update the running estimate
#
# The running estimate auto-update flow:
#   Agent updates estimate -> file mtime changes -> dashboard server's
#   file watcher detects change -> regenerates served HTML -> browser
#   polls and re-renders. This hook's job is to REMIND the agent to
#   update, not to update the estimate itself (that requires judgment).
#
# Freshness sources (checked in order):
#   1. JSON running estimate mtime (primary, always available)
#   2. Session DB updated_at (supplemental, if harness-db.py available)
#   If either source is fresh, suppress the stale reminder.
#
# Hook contract:
#   - Stop hook, command type (stderr -> shown to agent as feedback)
#   - Exit 0 = allow, Exit 2 = block (we always allow)
#   - Must be fast (<50ms) -- fires on every agent turn
#   - Must never crash or hang
#
# Related decisions:
#   D-CONTEXT-ROT-HOOK: Lagebeurteilung checkpoint at 20%+ context
#   D-OPERATIONAL-LEARNING-DUTY: OBSERVE-SURFACE-PROPOSE-CONNECT

set -euo pipefail

# Read JSON from stdin
input=$(cat)

# Extract session_id
session_id=""
if [[ "$input" =~ \"session_id\"[[:space:]]*:[[:space:]]*\"([^\"]+)\" ]]; then
    session_id="${BASH_REMATCH[1]}"
fi

[ -n "$session_id" ] || exit 0

# --- Turn tracking via marker directory ---
marker_dir="/tmp/aitools-estimate-$session_id"
mkdir -p "$marker_dir" 2>/dev/null || exit 0

# Increment turn count
turn_file="$marker_dir/turn-count"
turn_count=0
if [ -f "$turn_file" ]; then
    turn_count=$(cat "$turn_file" 2>/dev/null || echo "0")
    if ! [[ "$turn_count" =~ ^[0-9]+$ ]]; then turn_count=0; fi
fi
turn_count=$((turn_count + 1))
printf '%d' "$turn_count" > "$turn_file"

# --- Lagebeurteilung checkpoint ---
# Heuristic: each agent turn uses ~2-5K tokens of context.
# At 200K total context, 20% = 40K tokens = ~10-20 turns.
# Inject reminder at turn 15, then every 15 turns after.
# This is conservative -- better to remind too early than too late.

LAGE_INTERVAL=15
reminders=""

last_lage_file="$marker_dir/last-lage-turn"
last_lage_turn=0
if [ -f "$last_lage_file" ]; then
    last_lage_turn=$(cat "$last_lage_file" 2>/dev/null || echo "0")
    if ! [[ "$last_lage_turn" =~ ^[0-9]+$ ]]; then last_lage_turn=0; fi
fi

turns_since_lage=$((turn_count - last_lage_turn))

if [ "$turn_count" -ge "$LAGE_INTERVAL" ] && [ "$turns_since_lage" -ge "$LAGE_INTERVAL" ]; then
    printf '%d' "$turn_count" > "$last_lage_file"

    reminders="Lagebeurteilung checkpoint (turn ${turn_count}): Context is growing. Update the running estimate with current situation, new findings, and decisions. If the dashboard server is running, the update will appear automatically. Key fields to refresh: schwerpunkt, situation.currentState, completedWork (append recent), findings (new ones), delegationLog (new entries), meta.version (increment). "
fi

# --- Estimate freshness check ---
# If a running estimate exists and hasn't been modified in 30+ minutes,
# remind the agent it may be stale.
if [ -z "$reminders" ] && [ "$turn_count" -ge 5 ]; then
    # Check every 10 turns
    if [ $((turn_count % 10)) -eq 0 ]; then
        # Find project root
        cwd=""
        if [[ "$input" =~ \"cwd\"[[:space:]]*:[[:space:]]*\"([^\"]+)\" ]]; then
            cwd="${BASH_REMATCH[1]}"
        fi

        if [ -n "$cwd" ]; then
            project_root=$(cd "$cwd" 2>/dev/null && git rev-parse --show-toplevel 2>/dev/null || echo "$cwd")

            # Check for running estimate
            estimate=""
            if [ -f "$project_root/.aitools/channel/running-estimate.json" ]; then
                estimate="$project_root/.aitools/channel/running-estimate.json"
            fi
            # Check scratch dirs
            if [ -z "$estimate" ] && [ -d "$project_root/.scratch" ]; then
                for dir in "$project_root"/.scratch/session-*/; do
                    [ -d "$dir" ] || continue
                    for est in "$dir"/*running-estimate*.json; do
                        [ -f "$est" ] || continue
                        estimate="$est"
                        break 2
                    done
                done
            fi

            if [ -n "$estimate" ]; then
                now=$(date +%s)
                # Platform dispatch: macOS BSD stat vs GNU stat (Linux/Git Bash)
                if [ "$(uname -s)" = "Darwin" ]; then
                    est_mod=$(stat -f %m "$estimate" 2>/dev/null || echo "$now")
                else
                    est_mod=$(stat -c %Y "$estimate" 2>/dev/null || echo "$now")
                fi
                est_age=$((now - est_mod))
                if [ "$est_age" -gt 1800 ]; then
                    # Before flagging stale, check if session DB was recently updated
                    # (supplemental: agent may have written to DB but not exported yet)
                    db_fresh=false
                    if [ -n "$session_id" ] && [ -d "$project_root/.aitools/sessions" ]; then
                        db_prefix=$(printf '%s' "$session_id" | cut -c1-10)
                        db_file="$project_root/.aitools/sessions/${db_prefix}.db"
                        if [ -f "$db_file" ]; then
                            if [ "$(uname -s)" = "Darwin" ]; then
                                db_mod=$(stat -f %m "$db_file" 2>/dev/null || echo "0")
                            else
                                db_mod=$(stat -c %Y "$db_file" 2>/dev/null || echo "0")
                            fi
                            db_age=$((now - db_mod))
                            if [ "$db_age" -lt 1800 ]; then
                                db_fresh=true
                            fi
                        fi
                    fi
                    if [ "$db_fresh" = false ]; then
                        minutes=$((est_age / 60))
                        reminders="Running estimate is ${minutes} minutes stale. Consider updating it with current session state. "
                    fi
                fi
            fi
        fi
    fi
fi

# Output reminders (if any) to stderr (shown to agent as feedback)
if [ -n "$reminders" ]; then
    printf '%s' "$reminders" >&2
fi

exit 0
__EMB_ESTIMREFRESH__
cat > "$HOOKS_DIR/harness-db-sessionstart.sh" <<'__EMB_HDBSTART__'
#!/usr/bin/env bash
# harness-db-sessionstart.sh -- Claude Code SessionStart hook
# Initializes harness databases and registers the current session.
#
# Design decisions:
#   - Requires Python 3 (sqlite3 stdlib -- no external deps)
#   - Creates harness DB + session DB via harness-db.py helper
#   - Silent exit on errors (hook must never break Claude Code)
#   - Cross-platform: Python sqlite3 works on macOS, Windows Git Bash, Linux
#   - Session ID from CC hook input (same pattern as scratch-init.sh)

set -euo pipefail

# --- Pure-bash JSON field extraction (same as scratch-init.sh) ---
json_field() {
    local json="$1" key="$2"
    local val
    val=$(printf '%s' "$json" \
        | grep -o "\"$key\"[[:space:]]*:[[:space:]]*\"[^\"]*\"" \
        | head -1 \
        | sed 's/.*"'"$key"'"[[:space:]]*:[[:space:]]*"//' \
        | sed 's/"$//')
    printf '%s' "$val"
}

# Read hook input from stdin (contains session_id, cwd, etc.)
INPUT=$(cat)
SESSION_ID=$(json_field "$INPUT" "session_id")

# Bail if no session ID (defensive)
if [ -z "$SESSION_ID" ]; then
    exit 0
fi

# Find project root
PROJECT_ROOT=$(git rev-parse --show-toplevel 2>/dev/null || echo "")
if [ -z "$PROJECT_ROOT" ]; then
    PROJECT_ROOT="$(pwd)"
fi

# Check for Python 3 (required for harness-db.py)
PYTHON=""
if command -v python3 > /dev/null 2>&1; then
    PYTHON="python3"
elif command -v python > /dev/null 2>&1; then
    PYTHON="python"
fi

if [ -z "$PYTHON" ]; then
    printf 'harness-db: Python 3 not found, skipping DB init\n'
    exit 0
fi

# Verify sqlite3 module is available
if ! "$PYTHON" -c "import sqlite3" 2>/dev/null; then
    printf 'harness-db: Python sqlite3 module not available, skipping DB init\n'
    exit 0
fi

HELPER="$PROJECT_ROOT/scripts/harness-db.py"

# Check helper script exists
if [ ! -f "$HELPER" ]; then
    exit 0
fi

# Initialize harness databases (creates if missing)
"$PYTHON" "$HELPER" init 2>/dev/null || true

# Register this session
"$PYTHON" "$HELPER" session start --id "$SESSION_ID" 2>/dev/null || true

printf 'Harness DB: session %s registered\n' "$SESSION_ID"
__EMB_HDBSTART__
cat > "$HOOKS_DIR/harness-db-sessionend.sh" <<'__EMB_HDBEND__'
#!/usr/bin/env bash
# harness-db-sessionend.sh -- Claude Code SessionEnd hook
# Marks the current session as complete and exports DB to JSON for
# git carry-forward (Option B: SQLite runtime, JSON archive).
#
# Design decisions:
#   - Requires Python 3 (sqlite3 stdlib -- no external deps)
#   - Exports session DB to .aitools/channel/running-estimate.json (tracked)
#   - Silent exit on errors (hook must never break Claude Code)
#   - Cross-platform: Python sqlite3 works on macOS, Windows Git Bash, Linux
#   - Session ID from CC hook input (same pattern as harvest-session.sh)

set -euo pipefail

# --- Pure-bash JSON field extraction (same as harvest-session.sh) ---
json_field() {
    local json="$1" key="$2"
    local val
    val=$(printf '%s' "$json" \
        | grep -o "\"$key\"[[:space:]]*:[[:space:]]*\"[^\"]*\"" \
        | head -1 \
        | sed 's/.*"'"$key"'"[[:space:]]*:[[:space:]]*"//' \
        | sed 's/"$//')
    printf '%s' "$val"
}

# Read hook input from stdin
INPUT=$(cat)
SESSION_ID=$(json_field "$INPUT" "session_id")

# Bail if no session ID (defensive)
if [ -z "$SESSION_ID" ]; then
    exit 0
fi

# Find project root
CWD=$(json_field "$INPUT" "cwd")
if [ -n "$CWD" ]; then
    PROJECT_ROOT=$(cd "$CWD" 2>/dev/null && git rev-parse --show-toplevel 2>/dev/null || echo "$CWD")
else
    PROJECT_ROOT=$(git rev-parse --show-toplevel 2>/dev/null || echo "$(pwd)")
fi

# Check for Python 3
PYTHON=""
if command -v python3 > /dev/null 2>&1; then
    PYTHON="python3"
elif command -v python > /dev/null 2>&1; then
    PYTHON="python"
fi

if [ -z "$PYTHON" ]; then
    exit 0
fi

HELPER="$PROJECT_ROOT/scripts/harness-db.py"

# Check helper script exists
if [ ! -f "$HELPER" ]; then
    exit 0
fi

# Mark session as ended
"$PYTHON" "$HELPER" session end --id "$SESSION_ID" 2>/dev/null || true

# Export DB to JSON for git carry-forward
"$PYTHON" "$HELPER" export --format json --session "$SESSION_ID" 2>/dev/null || true

printf 'Harness DB: session %s ended, JSON exported\n' "$SESSION_ID"
__EMB_HDBEND__

    for _hf in "$HOOKS_DIR"/*.sh; do
        [ -f "$_hf" ] || continue
        chmod +x "$_hf"
        log_ok "Deployed hook: $_hf"
    done
fi

# Legacy dest vars for settings.json merge below
HOOK_DEST="$HOOKS_DIR/session-archive.sh"
GUARD_DEST="$HOOKS_DIR/standing-order-guard.sh"


# --- Merge hook into ~/.claude/settings.json ---
SETTINGS_FILE="$HOME/.claude/settings.json"
mkdir -p "$HOME/.claude"

# The hook commands — use deployed copies in ~/.claude/hooks/
HOOK_CMD="bash \"$HOOK_DEST\""
GUARD_CMD="bash \"$GUARD_DEST\""
GLOSSARY_CMD="bash \"$HOME/.claude/hooks/glossary-skill-guard.sh\""
SCRATCH_CMD="bash \"$SCRATCH_DEST\""
HARVEST_CMD="bash \"$HARVEST_DEST\""
SHFIXUP_CMD="bash \"$SHFIXUP_DEST\""
SURFACING_CMD="bash \"$SURFACING_DEST\""
BLOCK_GUIDE_CMD="bash \"$BLOCK_GUIDE_DEST\""
TOOL_OPS_AUDIT_CMD="bash \"$TOOL_OPS_AUDIT_DEST\""
DASHBOARD_CMD="bash \"$DASHBOARD_DEST\""
ESTIMATE_REFRESH_CMD="bash \"$ESTIMATE_REFRESH_DEST\""

MERGE_RESULT=$(node -e "
$SORT_KEYS_JS
const fs = require('fs');
const path = require('path');
const settingsFile = process.argv[1];
const hookCmd = process.argv[2];
const guardCmd = process.argv[3];
const glossaryCmd = process.argv[4];
const dryRun = process.argv[5] === 'true';
const force = process.argv[6] === 'true';
const scratchCmd = process.argv[7];
const harvestCmd = process.argv[8];
const shfixupCmd = process.argv[9];
const surfacingCmd = process.argv[10];
const blockGuideCmd = process.argv[11];
const toolOpsAuditCmd = process.argv[12];
const dashboardCmd = process.argv[13];
const estimateRefreshCmd = process.argv[14];
// --- Embedded preferences (from profile.json at build time) ---
const autoMemory = false;
const alwaysThinking = true;
const effortLevel = "high";
const validEffortLevels = ['low', 'medium', 'high'];

// --- Read existing settings.json ---
let settings = {};
let corrupt = false;
try {
    settings = JSON.parse(fs.readFileSync(settingsFile, 'utf8'));
} catch (e) {
    if (e.code !== 'ENOENT') {
        corrupt = true;
        console.error('Warning: ' + settingsFile + ' is invalid JSON');
    }
}
const beforeKeys = Object.keys(settings);

// --- Merge hooks ---
if (!settings.hooks) settings.hooks = {};

// Helper: ensure exactly one entry for a hookId in an event array.
// Updates the command if found, adds if not, deduplicates extras.
function mergeHookEntry(eventName, hookId, matcher, cmd, hookType) {
    hookType = hookType || 'command';
    if (!Array.isArray(settings.hooks[eventName])) settings.hooks[eventName] = [];
    const arr = settings.hooks[eventName];

    // Find first matching entry and update it
    let found = false;
    for (const rule of arr) {
        if (rule.hooks && rule.hooks.some(h => h.command && h.command.includes(hookId))) {
            if (!found) {
                rule.hooks.forEach(h => {
                    if (h.command && h.command.includes(hookId)) {
                        h.command = cmd;
                        h.type = hookType;
                    }
                });
                rule.matcher = matcher;
                found = true;
            }
        }
    }
    if (!found) {
        arr.push({ matcher, hooks: [{ type: hookType, command: cmd }] });
    }

    // Deduplicate: keep only the first entry matching hookId
    let seen = false;
    settings.hooks[eventName] = arr.filter(rule => {
        const isMatch = rule.hooks && rule.hooks.some(h => h.command && h.command.includes(hookId));
        if (isMatch) {
            if (seen) return false;
            seen = true;
        }
        return true;
    });
}

mergeHookEntry('SessionEnd', 'session-archive.sh', '', hookCmd);
mergeHookEntry('SessionEnd', 'harvest-session.sh', '', harvestCmd);
mergeHookEntry('SessionStart', 'scratch-init.sh', '', scratchCmd);
mergeHookEntry('PreToolUse', 'standing-order-guard.sh', 'Bash', guardCmd);
mergeHookEntry('PreToolUse', 'glossary-skill-guard.sh', 'Read|Grep', glossaryCmd);
mergeHookEntry('PostToolUse', 'sh-file-fixup.sh', 'Write|Edit', shfixupCmd);
mergeHookEntry('Stop', 'surfacing-duty-stop.sh', '', surfacingCmd);
mergeHookEntry('PreToolUse', 'block-claude-code-guide.sh', 'Agent', blockGuideCmd);
mergeHookEntry('SessionEnd', 'tool-ops-session-audit.sh', '', toolOpsAuditCmd);
mergeHookEntry('SessionStart', 'dashboard-serve.sh', '', dashboardCmd);
mergeHookEntry('Stop', 'estimate-refresh-stop.sh', '', estimateRefreshCmd);

// --- Track old values for change reporting ---
const oldAutoMemory = settings.autoMemoryEnabled;
const oldAlwaysThinking = settings.alwaysThinkingEnabled;
const oldEffortLevel = settings.effortLevel;

// --- Merge claude preferences ---
settings.autoMemoryEnabled = autoMemory;
settings.alwaysThinkingEnabled = alwaysThinking;
if (effortLevel) settings.effortLevel = effortLevel;

// --- Detect preference changes ---
const prefChanges = [];
if (oldAutoMemory !== settings.autoMemoryEnabled) prefChanges.push('CHANGED: autoMemoryEnabled: ' + (oldAutoMemory !== undefined ? oldAutoMemory : '(not set)') + ' -> ' + settings.autoMemoryEnabled);
if (oldAlwaysThinking !== settings.alwaysThinkingEnabled) prefChanges.push('CHANGED: alwaysThinkingEnabled: ' + (oldAlwaysThinking !== undefined ? oldAlwaysThinking : '(not set)') + ' -> ' + settings.alwaysThinkingEnabled);
if (effortLevel && oldEffortLevel !== settings.effortLevel) prefChanges.push('CHANGED: effortLevel: ' + (oldEffortLevel || '(not set)') + ' -> ' + settings.effortLevel);

// --- Clobber detection ---
const managedKeys = ['hooks', 'autoMemoryEnabled', 'alwaysThinkingEnabled', 'effortLevel'];
const afterKeys = Object.keys(settings);
const lostKeys = beforeKeys.filter(k => !afterKeys.includes(k));

if (dryRun) {
    console.error('[DRY RUN] ' + settingsFile + ': merge');
    console.error('  Managed fields: ' + managedKeys.join(', '));
    if (lostKeys.length > 0) console.error('  CLOBBER WARNING: would lose: ' + lostKeys.join(', '));
    if (corrupt) console.error('  File is corrupt -- --force required');
    console.error('  SessionEnd hook: ' + hookCmd);
    console.error('  PreToolUse hook: ' + guardCmd);
    console.error('  autoMemoryEnabled: ' + autoMemory);
    console.error('  alwaysThinkingEnabled: ' + alwaysThinking);
    if (effortLevel) console.error('  effortLevel: ' + effortLevel);
    console.log('dry-run');
} else if (corrupt && !force) {
    console.error('ERROR: ' + settingsFile + ' is corrupt. Use --force to overwrite, or fix manually.');
    console.log('error-corrupt');
} else if (lostKeys.length > 0 && !force) {
    console.error('ERROR: merge would lose fields: ' + lostKeys.join(', ') + '. Use --force to proceed.');
    console.log('error-clobber');
} else {
    if (corrupt) console.error('Warning: proceeding with --force on corrupt file');
    if (lostKeys.length > 0) console.error('Warning: proceeding with --force, losing fields: ' + lostKeys.join(', '));
    const newJson = JSON.stringify(sortKeys(settings), null, 2) + '\n';
    let existingJson = '';
    try { existingJson = fs.readFileSync(settingsFile, 'utf8'); } catch(e) { /* file may not exist */ }
    const existingNorm = existingJson ? JSON.stringify(sortKeys(JSON.parse(existingJson))) : '';
    const mergedNorm = JSON.stringify(sortKeys(settings));
    if (mergedNorm === existingNorm) {
        console.log('unchanged');
    } else {
        fs.writeFileSync(settingsFile, newJson);

        // Post-write validation
        const _v = JSON.parse(fs.readFileSync(settingsFile, 'utf8'));
        const _required = ['hooks', 'autoMemoryEnabled', 'alwaysThinkingEnabled'];
        if (effortLevel) _required.push('effortLevel');
        const _missing = _required.filter(k => !(k in _v));
        if (_missing.length) { console.error('Validation failed: missing ' + _missing.join(', ')); process.exit(1); }
        // Validate hook arrays have exactly one entry per managed hook
        const seArchiveCount = (_v.hooks.SessionEnd || []).filter(r => r.hooks && r.hooks.some(h => h.command && h.command.includes('session-archive.sh'))).length;
        const seHarvestCount = (_v.hooks.SessionEnd || []).filter(r => r.hooks && r.hooks.some(h => h.command && h.command.includes('harvest-session.sh'))).length;
        const ssCount = (_v.hooks.SessionStart || []).filter(r => r.hooks && r.hooks.some(h => h.command && h.command.includes('scratch-init.sh'))).length;
        const ptCount = (_v.hooks.PreToolUse || []).filter(r => r.hooks && r.hooks.some(h => h.command && h.command.includes('standing-order-guard.sh'))).length;
        if (seArchiveCount !== 1) { console.error('Validation failed: expected 1 SessionEnd session-archive hook, got ' + seArchiveCount); process.exit(1); }
        if (seHarvestCount !== 1) { console.error('Validation failed: expected 1 SessionEnd harvest-session hook, got ' + seHarvestCount); process.exit(1); }
        if (ssCount !== 1) { console.error('Validation failed: expected 1 SessionStart scratch-init hook, got ' + ssCount); process.exit(1); }
        if (ptCount !== 1) { console.error('Validation failed: expected 1 PreToolUse standing-order-guard hook, got ' + ptCount); process.exit(1); }
        const glCount = (_v.hooks.PreToolUse || []).filter(r => r.hooks && r.hooks.some(h => h.command && h.command.includes('glossary-skill-guard.sh'))).length;
        if (glCount !== 1) { console.error('Validation failed: expected 1 PreToolUse glossary-skill-guard hook, got ' + glCount); process.exit(1); }
        const bgCount = (_v.hooks.PreToolUse || []).filter(r => r.hooks && r.hooks.some(h => h.command && h.command.includes('block-claude-code-guide.sh'))).length;
        if (bgCount !== 1) { console.error('Validation failed: expected 1 PreToolUse block-claude-code-guide hook, got ' + bgCount); process.exit(1); }
        const toaCount = (_v.hooks.SessionEnd || []).filter(r => r.hooks && r.hooks.some(h => h.command && h.command.includes('tool-ops-session-audit.sh'))).length;
        if (toaCount !== 1) { console.error('Validation failed: expected 1 SessionEnd tool-ops-session-audit hook, got ' + toaCount); process.exit(1); }
        const dashCount = (_v.hooks.SessionStart || []).filter(r => r.hooks && r.hooks.some(h => h.command && h.command.includes('dashboard-serve.sh'))).length;
        if (dashCount !== 1) { console.error('Validation failed: expected 1 SessionStart dashboard-serve hook, got ' + dashCount); process.exit(1); }
        const erCount = (_v.hooks.Stop || []).filter(r => r.hooks && r.hooks.some(h => h.command && h.command.includes('estimate-refresh-stop.sh'))).length;
        if (erCount !== 1) { console.error('Validation failed: expected 1 Stop estimate-refresh-stop hook, got ' + erCount); process.exit(1); }

        // Validate hook schema: command-type must have command field,
        // prompt-type must have prompt field (not command).
        // Catches the type mismatch that broke settings.json in v0.60.
        for (const [event, rules] of Object.entries(_v.hooks || {})) {
            for (const rule of (rules || [])) {
                for (const h of (rule.hooks || [])) {
                    if (h.type === 'command' && !h.command) {
                        console.error('Validation failed: ' + event + ' hook has type "command" but no command field');
                        process.exit(1);
                    }
                    if (h.type === 'prompt') {
                        if (!h.prompt) {
                            console.error('Validation failed: ' + event + ' hook has type "prompt" but no prompt field. Prompt-type hooks require a static string in the prompt field, not a command path.');
                            process.exit(1);
                        }
                        if (h.command) {
                            console.error('Validation failed: ' + event + ' hook has type "prompt" with a command field. Prompt-type hooks use the prompt field for static text. Use type "command" for script execution.');
                            process.exit(1);
                        }
                    }
                }
            }
        }

        console.log('ok');
        prefChanges.forEach(c => console.log(c));
    }
}
" "$SETTINGS_FILE" "$HOOK_CMD" "$GUARD_CMD" "$GLOSSARY_CMD" "$DRY_RUN" "$FORCE" "$SCRATCH_CMD" "$HARVEST_CMD" "$SHFIXUP_CMD" "$SURFACING_CMD" "$BLOCK_GUIDE_CMD" "$TOOL_OPS_AUDIT_CMD" "$DASHBOARD_CMD" "$ESTIMATE_REFRESH_CMD")

# Parse merge result: first line is status, CHANGED: lines are key changes
MERGE_STATUS=$(echo "$MERGE_RESULT" | head -1)

case "$MERGE_STATUS" in
    ok)
        log_ok "Settings deployed to $(display_path "$SETTINGS_FILE")"
        HOOKS_CHANGED=true
        log "  SessionEnd hook: $HOOK_CMD"
        log "  PreToolUse hook: $GUARD_CMD"
        log "  autoMemoryEnabled: $(node -e "console.log(JSON.parse(require('fs').readFileSync('$SETTINGS_FILE','utf8')).autoMemoryEnabled)")"
        log "  alwaysThinkingEnabled: $(node -e "console.log(JSON.parse(require('fs').readFileSync('$SETTINGS_FILE','utf8')).alwaysThinkingEnabled)")"
        log "  effortLevel: $(node -e "const s=JSON.parse(require('fs').readFileSync('$SETTINGS_FILE','utf8')); console.log(s.effortLevel || '(not set)')")"
        emit_merge_details "$MERGE_RESULT" "claude hooks"
        ;;
    unchanged)
        log_ok "Settings unchanged: $(display_path "$SETTINGS_FILE")"
        ;;
    dry-run)
        log "[DRY RUN] Would merge settings (see above)"
        ;;
    error-corrupt)
        log_error "$(display_path "$SETTINGS_FILE") is corrupt. Use --force to overwrite."
        write_summary ERROR "claude hooks" "settings corrupt"
        ;;
    error-clobber)
        log_error "$(display_path "$SETTINGS_FILE") merge would lose fields. Use --force to proceed."
        write_summary ERROR "claude hooks" "merge would lose fields"
        ;;
    *)
        log_error "Unexpected merge result: $MERGE_RESULT"
        write_summary ERROR "claude hooks" "unexpected error"
        ;;
esac
if [ "$ERRORS" -gt 0 ]; then
    log "FAILED with $ERRORS error(s)" "error"
    exit 1
elif [ "$WARNINGS" -gt 0 ]; then
    log "COMPLETED with $WARNINGS warning(s)" "warn"
    exit 0
else
    log "COMPLETED successfully" "ok"
    exit 0
fi
